const MATH_CHAPTERS = [{"num":1,"title":"Số hữu tỉ","icon":"①"},{"num":2,"title":"Số thực","icon":"②"},{"num":3,"title":"Góc và đường thẳng song song","icon":"③"},{"num":4,"title":"Tam giác bằng nhau","icon":"④"},{"num":5,"title":"Thu thập và biểu diễn dữ liệu","icon":"⑤"}];
const MATH_QUESTIONS = [{"id":"m1-1","ch":1,"topic":"Số hữu tỉ","q":"Số hữu tỉ x được viết dưới dạng nào?","options":["x = a/b ; a, b ∈ ℤ ; b ≠ 0","x = a/b ; a, b ∈ ℤ ; a ≠ 0","x = a/b ; a, b ∈ ℕ ; b ≠ 0","x = a/b ; a, b ∈ ℤ ; b = 0"],"correct":0,"answer":"x = a/b ; a, b ∈ ℤ ; b ≠ 0","explanation":"🔑 x ∈ ℚ ⇔ x = a/b với a, b ∈ ℤ và b ≠ 0.<br>✗ a ≠ 0: tử được phép bằng 0, như 0/5.<br>✗ a, b ∈ ℕ: mất hết số âm như −3/4.<br>✗ b = 0: không chia được cho 0."},{"id":"m1-2","ch":1,"topic":"Số hữu tỉ","q":"Trong cách viết x = a/b của một số hữu tỉ, mẫu số b phải thoả điều kiện nào?","options":["b > 0","b ≠ 1","b ≠ 0","b ∈ ℕ"],"correct":2,"answer":"b ≠ 0","explanation":"🔑 Mẫu chỉ cần khác 0, vì không chia được cho 0.<br>✗ b > 0: mẫu âm vẫn được, như 3/(−4).<br>✗ b ≠ 1: mẫu 1 vẫn được, như 5 = 5/1.<br>✗ b ∈ ℕ: mẫu là số nguyên, được âm."},{"id":"m1-3","ch":1,"topic":"Số đối","q":"Số đối của số hữu tỉ a/b là số nào?","options":["b/a","−a/b","|a/b|","a/b"],"correct":1,"answer":"−a/b","explanation":"🔑 Số đối chỉ đổi dấu: số đối của a/b là −a/b.<br>✗ b/a: đó là nghịch đảo, tích bằng 1.<br>✗ |a/b|: đó là giá trị tuyệt đối.<br>✗ a/b: là số ban đầu, chưa đổi dấu."},{"id":"m1-4","ch":1,"topic":"Số đối","q":"Số đối của −3/5 là số nào?","options":["−5/3","5/3","−3/5","3/5"],"correct":3,"answer":"3/5","explanation":"🔑 Đổi dấu là xong: số đối của −3/5 là 3/5, vì −3/5 + 3/5 = 0.<br>✗ −5/3: đó là nghịch đảo của −3/5, vì (−3/5) · (−5/3) = 1, không phải số đối.<br>✗ 5/3: lật tử mẫu rồi bỏ dấu âm, không phải cách tìm số đối.<br>✗ −3/5: chính là số ban đầu, chưa đổi dấu."},{"id":"m1-5","ch":1,"topic":"Số đối","q":"Tổng của một số hữu tỉ và số đối của nó bằng bao nhiêu?","options":["0","1","2 · (a/b)","−1"],"correct":0,"answer":"0","explanation":"🔑 a/b + (−a/b) = 0: hai số đối luôn triệt tiêu.<br>✗ 1: đó là tích của hai số nghịch đảo.<br>✗ 2 · (a/b): đó là cộng với chính nó.<br>✗ −1: tổng hai số đối bằng 0, không âm."},{"id":"m1-6","ch":1,"topic":"Số hữu tỉ","q":"Cách viết nào sau đây KHÔNG cho ta một số hữu tỉ?","options":["0/3","3/0","−7/1","2/5"],"correct":1,"answer":"3/0","explanation":"🔑 Mẫu phải khác 0, nên 3/0 vô nghĩa, không phải số hữu tỉ.<br>✗ 0/3 = 0: tử bằng 0 vẫn hợp lệ.<br>✗ −7/1: số nguyên nào cũng viết được a/1.<br>✗ 2/5: mẫu 5 ≠ 0, hoàn toàn hợp lệ."},{"id":"m1-7","ch":1,"topic":"Số hữu tỉ","q":"Vì sao mọi số nguyên a đều là số hữu tỉ?","options":["a = 1/a","a = a/0","a = a/1","a = 0/a"],"correct":2,"answer":"a = a/1","explanation":"🔑 Mọi số nguyên a đều viết được dưới dạng phân số a/1 với mẫu 1 ≠ 0, nên a là số hữu tỉ. Ví dụ trong SGK: −7 = −7/1.<br>✗ a = 1/a: chỉ đúng khi a = 1 hoặc a = −1, không đúng cho mọi số nguyên.<br>✗ a = a/0: mẫu bằng 0 là vô nghĩa, vì không chia được cho 0.<br>✗ a = 0/a: khi a ≠ 0 thì 0/a luôn bằng 0, không bằng a; còn khi a = 0 thì 0/0 vô nghĩa vì mẫu phải khác 0."},{"id":"m1-8","ch":1,"topic":"Số hữu tỉ","q":"Kí hiệu nào diễn tả đúng câu: x là số hữu tỉ?","options":["x ∈ ℚ","x ∈ ℤ","x ∈ ℕ","ℚ ∈ x"],"correct":0,"answer":"x ∈ ℚ","explanation":"🔑 Tập số hữu tỉ kí hiệu là ℚ, nên viết x ∈ ℚ.<br>✗ x ∈ ℤ: đó là số nguyên, hẹp hơn ℚ.<br>✗ x ∈ ℕ: đó là số tự nhiên, hẹp hơn nữa.<br>✗ ℚ ∈ x: viết ngược, phần tử đứng trước."},{"id":"m1-9","ch":1,"topic":"Số đối","q":"Số đối của số hữu tỉ x được kí hiệu là gì?","options":["1/x","|x|","x⁻¹","−x"],"correct":3,"answer":"−x","explanation":"🔑 Số đối của x là −x, vì x + (−x) = 0.<br>✗ 1/x: là nghịch đảo, tích bằng 1.<br>✗ |x|: là giá trị tuyệt đối, luôn ≥ 0.<br>✗ x⁻¹: cũng là 1/x, vẫn là nghịch đảo."},{"id":"m1-10","ch":1,"topic":"Số hữu tỉ","q":"Phân số nào dưới đây biểu diễn CÙNG một số hữu tỉ với 2/3?","options":["3/2","4/6","2/6","4/3"],"correct":1,"answer":"4/6","explanation":"🔑 Nhân cả tử VÀ mẫu với 2 thì giá trị không đổi: 2/3 = 4/6.<br>✗ 3/2: đó là phân số nghịch đảo.<br>✗ 2/6: chỉ nhân mẫu, quên nhân tử.<br>✗ 4/3: chỉ nhân tử, quên nhân mẫu."},{"id":"m1-11","ch":1,"topic":"Số đối","q":"Cho x = 7/(−4). Số đối của x là số nào?","options":["−7/4","−4/7","7/4","4/7"],"correct":2,"answer":"7/4","explanation":"🔑 7/(−4) = −7/4; đổi dấu ta được số đối là 7/4, vì −7/4 + 7/4 = 0.<br>✗ −7/4: chính là x viết gọn lại, chưa đổi dấu.<br>✗ −4/7: đó là nghịch đảo của x, vì 7/(−4) · (−4/7) = 1, không phải số đối.<br>✗ 4/7: lật tử mẫu rồi bỏ dấu, không phải cách tìm số đối."},{"id":"m1-12","ch":1,"topic":"Số hữu tỉ","q":"Điều kiện nào KHÔNG bắt buộc trong định nghĩa số hữu tỉ x = a/b?","options":["a ≠ 0","b ≠ 0","a ∈ ℤ","b ∈ ℤ"],"correct":0,"answer":"a ≠ 0","explanation":"🔑 Chỉ cần a, b ∈ ℤ và b ≠ 0; tử được phép bằng 0 (0/7 = 0).<br>✗ b ≠ 0: bắt buộc, bỏ đi thì vô nghĩa.<br>✗ a ∈ ℤ: bắt buộc, tử phải là số nguyên.<br>✗ b ∈ ℤ: bắt buộc, mẫu phải là số nguyên."},{"id":"m1-13","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A + B = C, quy tắc chuyển vế cho ta điều gì?","options":["A = C + B","A = C − B","A = B − C","A = B + C"],"correct":1,"answer":"A = C − B","explanation":"🔑 Qua vế kia thì đổi dấu: A + B = C ⇒ A = C − B.<br>✗ A = C + B: quên đổi dấu.<br>✗ A = B − C: đảo thứ tự nên trái dấu.<br>✗ A = B + C: sai cả dấu lẫn vị trí."},{"id":"m1-14","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A − B = C, quy tắc chuyển vế cho ta điều gì?","options":["A = C − B","A = B − C","A = −C − B","A = C + B"],"correct":3,"answer":"A = C + B","explanation":"🔑 A − B = C ⇒ A = C + B: dấu trừ qua vế kia thành dấu cộng.<br>✗ A = C − B: quên đổi dấu.<br>✗ A = B − C: đảo thứ tự nên trái dấu.<br>✗ A = −C − B: đổi dấu cả hai số hạng."},{"id":"m1-15","ch":1,"topic":"Chuyển vế","q":"Khi chuyển một số hạng từ vế này sang vế kia của một đẳng thức, ta phải làm gì với số hạng đó?","options":["Giữ nguyên dấu","Đổi dấu","Lấy nghịch đảo","Bình phương lên"],"correct":1,"answer":"Đổi dấu","explanation":"🔑 Chuyển vế thì đổi dấu số hạng đó: + thành −, − thành +.<br>✗ Giữ nguyên dấu: 2 + x = 9 ⇒ x = 9 + 2.<br>✗ Lấy nghịch đảo: đó là chuyện nhân chia.<br>✗ Bình phương lên: không có quy tắc đó."},{"id":"m1-16","ch":1,"topic":"Chuyển vế","q":"Tìm x biết x + 3/4 = 5/4. Bước chuyển vế đúng là gì?","options":["x = 5/4 − 3/4","x = 5/4 + 3/4","x = 3/4 − 5/4","x = 5/4 · 3/4"],"correct":0,"answer":"x = 5/4 − 3/4","explanation":"🔑 Chuyển 3/4 sang phải và đổi dấu: x = 5/4 − 3/4 = 1/2.<br>✗ x = 5/4 + 3/4: quên đổi dấu.<br>✗ x = 3/4 − 5/4: đảo thứ tự, trái dấu.<br>✗ x = 5/4 · 3/4: chuyển vế không nhân."},{"id":"m1-17","ch":1,"topic":"Chuyển vế","q":"Tìm x biết x − 2/5 = 1/5. Bước chuyển vế đúng là gì?","options":["x = 1/5 − 2/5","x = 2/5 − 1/5","x = 1/5 + 2/5","x = 1/5 : 2/5"],"correct":2,"answer":"x = 1/5 + 2/5","explanation":"🔑 A − B = C ⇒ A = C + B, nên x = 1/5 + 2/5 = 3/5.<br>✗ x = 1/5 − 2/5: quên đổi dấu.<br>✗ x = 2/5 − 1/5: đảo vị trí hai số hạng.<br>✗ x = 1/5 : 2/5: chuyển vế không chia."},{"id":"m1-18","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức x + a = b, giá trị của x là gì?","options":["x = b + a","x = a − b","x = a + b","x = b − a"],"correct":3,"answer":"x = b − a","explanation":"🔑 Chuyển a sang vế phải và đổi dấu: x = b − a.<br>✗ x = b + a: quên đổi dấu của a.<br>✗ x = a − b: đảo thứ tự nên trái dấu.<br>✗ x = a + b: sai cả dấu lẫn vị trí."},{"id":"m1-19","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A + B = C, biểu thức đúng của B là gì?","options":["B = C − A","B = C + A","B = A − C","B = A + C"],"correct":0,"answer":"B = C − A","explanation":"🔑 Chuyển A sang vế phải và đổi dấu: B = C − A.<br>✗ B = C + A: quên đổi dấu của A.<br>✗ B = A − C: đảo thứ tự nên trái dấu.<br>✗ B = A + C: sai cả dấu lẫn vị trí."},{"id":"m1-20","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A − B = C, biểu thức đúng của B là gì?","options":["B = C − A","B = C + A","B = A − C","B = A + C"],"correct":2,"answer":"B = A − C","explanation":"🔑 A − B = C ⇒ A = C + B ⇒ B = A − C.<br>✗ B = C − A: đảo thứ tự nên trái dấu.<br>✗ B = C + A: sai dấu của A.<br>✗ B = A + C: quên đổi dấu của C."},{"id":"m1-21","ch":1,"topic":"Chuyển vế","q":"Tìm x biết x + (−1/3) = 2/3. Giá trị của x là bao nhiêu?","options":["1/3","−1/3","−1","1"],"correct":3,"answer":"1","explanation":"🔑 Số hạng âm qua vế kia thành cộng: x = 2/3 + 1/3 = 1.<br>✗ 1/3: trừ 1/3 thay vì cộng.<br>✗ −1/3: sai dấu ở kết quả.<br>✗ −1: đổi dấu luôn cả 2/3."},{"id":"m1-22","ch":1,"topic":"Chuyển vế","q":"Tìm x biết 5 − x = 2. Giá trị của x là bao nhiêu?","options":["−3","3","7","−7"],"correct":1,"answer":"3","explanation":"🔑 Chuyển −x sang vế phải: 5 = 2 + x, rồi chuyển 2 sang vế trái: x = 5 − 2 = 3. Thử lại: 5 − 3 = 2 ✔<br>✗ −3: tính −x = 2 − 5 = −3 rồi quên đổi dấu ở bước cuối; −x = −3 thì x = 3.<br>✗ 7: lấy 5 + 2, nhưng thử lại 5 − 7 = −2, không bằng 2.<br>✗ −7: vừa cộng sai vừa thêm dấu âm; thử lại 5 − (−7) = 12."},{"id":"m1-23","ch":1,"topic":"Chuyển vế","q":"Đẳng thức nào là kết quả chuyển vế ĐÚNG của x − 3 = 7?","options":["x = 7 − 3","x = 3 − 7","x = −7 − 3","x = 7 + 3"],"correct":3,"answer":"x = 7 + 3","explanation":"🔑 Số hạng −3 qua vế phải thành +3: x = 7 + 3 = 10.<br>✗ x = 7 − 3: giữ nguyên dấu trừ.<br>✗ x = 3 − 7: đảo vị trí, ra số âm.<br>✗ x = −7 − 3: đổi dấu nhầm vế phải."},{"id":"m1-24","ch":1,"topic":"Chuyển vế","q":"Bạn An giải: từ 2 + x = 9 suy ra x = 9 + 2. Bạn ấy sai ở chỗ nào?","options":["Chuyển số 2 sang vế phải mà không đổi dấu","Chuyển số 2 sang vế phải và đã đổi dấu","Cộng hai vế với 2","Nhân hai vế với 2"],"correct":0,"answer":"Chuyển số 2 sang vế phải mà không đổi dấu","explanation":"🔑 Chuyển vế phải đổi dấu: 2 + x = 9 ⇒ x = 9 − 2 = 7.<br>✗ Đã đổi dấu: nếu vậy phải viết 9 − 2.<br>✗ Cộng hai vế với 2: vế trái thành 4 + x.<br>✗ Nhân hai vế với 2: An không hề nhân."},{"id":"m1-25","ch":1,"topic":"Lũy thừa","q":"Với x ≠ 0, giá trị của x⁰ là bao nhiêu?","options":["0","1","x","1/x"],"correct":1,"answer":"1","explanation":"🔑 Quy ước: mọi số khác 0 có mũ 0 đều bằng 1, nên x⁰ = 1. Ví dụ 5⁰ = 1, (−2)⁰ = 1.<br>✗ 0: nhầm số mũ 0 với kết quả bằng 0.<br>✗ x: đó là x¹, vì x¹ = x.<br>✗ 1/x: đó là nghịch đảo của x, không phải x⁰."},{"id":"m1-26","ch":1,"topic":"Lũy thừa","q":"Giá trị của x¹ là bao nhiêu?","options":["x","1","0","x²"],"correct":0,"answer":"x","explanation":"🔑 Số mũ 1 giữ nguyên cơ số: x¹ = x.<br>✗ 1: đó là x⁰ (x ≠ 0).<br>✗ 0: không công thức nào cho kết quả này.<br>✗ x²: nhầm số mũ 1 thành 2."},{"id":"m1-27","ch":1,"topic":"Lũy thừa","q":"Công thức nào đúng khi nhân hai lũy thừa cùng cơ số?","options":["xᵐ · xⁿ = xᵐⁿ","xᵐ · xⁿ = xᵐ⁻ⁿ","xᵐ · xⁿ = xᵐ⁺ⁿ","xᵐ · xⁿ = (x·x)ᵐ⁺ⁿ"],"correct":2,"answer":"xᵐ · xⁿ = xᵐ⁺ⁿ","explanation":"🔑 xᵐ · xⁿ = xᵐ⁺ⁿ: nhân thì giữ cơ số, cộng số mũ.<br>✗ xᵐⁿ: nhân số mũ, đó là (xᵐ)ⁿ.<br>✗ xᵐ⁻ⁿ: trừ số mũ, đó là phép chia.<br>✗ (x·x)ᵐ⁺ⁿ: cơ số phải giữ nguyên."},{"id":"m1-28","ch":1,"topic":"Lũy thừa","q":"Công thức nào đúng khi chia hai lũy thừa cùng cơ số (x ≠ 0)?","options":["xᵐ : xⁿ = xᵐ⁺ⁿ","xᵐ : xⁿ = xᵐⁿ","xᵐ : xⁿ = xⁿ⁻ᵐ","xᵐ : xⁿ = xᵐ⁻ⁿ"],"correct":3,"answer":"xᵐ : xⁿ = xᵐ⁻ⁿ","explanation":"🔑 xᵐ : xⁿ = xᵐ⁻ⁿ: chia thì giữ cơ số, trừ số mũ.<br>✗ xᵐ⁺ⁿ: cộng số mũ, đó là phép nhân.<br>✗ xᵐⁿ: nhân số mũ, đó là (xᵐ)ⁿ.<br>✗ xⁿ⁻ᵐ: trừ ngược, số mũ trái dấu."},{"id":"m1-29","ch":1,"topic":"Lũy thừa","q":"Công thức lũy thừa của một lũy thừa là công thức nào?","options":["(xᵐ)ⁿ = xᵐ⁺ⁿ","(xᵐ)ⁿ = xᵐⁿ","(xᵐ)ⁿ = xᵐ⁻ⁿ","(xᵐ)ⁿ = mⁿ · x"],"correct":1,"answer":"(xᵐ)ⁿ = xᵐⁿ","explanation":"🔑 (xᵐ)ⁿ = xᵐⁿ: lũy thừa của lũy thừa thì nhân hai số mũ.<br>✗ xᵐ⁺ⁿ: cộng số mũ, đó là xᵐ · xⁿ.<br>✗ xᵐ⁻ⁿ: trừ số mũ, đó là xᵐ : xⁿ.<br>✗ mⁿ · x: số mũ không xuống làm cơ số."},{"id":"m1-30","ch":1,"topic":"Lũy thừa","q":"Công thức lũy thừa của một tích là công thức nào?","options":["(xy)ⁿ = xⁿyⁿ","(xy)ⁿ = xⁿ + yⁿ","(xy)ⁿ = (xy) · n","(xy)ⁿ = xⁿy"],"correct":0,"answer":"(xy)ⁿ = xⁿyⁿ","explanation":"🔑 (xy)ⁿ = xⁿyⁿ: số mũ chia đều cho từng thừa số.<br>✗ xⁿ + yⁿ: đổi phép nhân thành cộng.<br>✗ (xy) · n: nhân với n, không lên mũ.<br>✗ xⁿy: quên nâng lũy thừa cho y."},{"id":"m1-31","ch":1,"topic":"Lũy thừa","q":"Công thức lũy thừa của một phân số x/y (y ≠ 0) là công thức nào?","options":["(x/y)ⁿ = xⁿ/y","(x/y)ⁿ = x/yⁿ","(x/y)ⁿ = xⁿ/yⁿ","(x/y)ⁿ = xⁿ − yⁿ"],"correct":2,"answer":"(x/y)ⁿ = xⁿ/yⁿ","explanation":"🔑 Quy tắc lũy thừa của một phân số (SGK gọi là lũy thừa của một thương): (x/y)ⁿ = xⁿ/yⁿ với y ≠ 0 — cả tử lẫn mẫu đều lên mũ n.<br>✗ xⁿ/y: quên nâng lũy thừa cho mẫu.<br>✗ x/yⁿ: quên nâng lũy thừa cho tử.<br>✗ xⁿ − yⁿ: chia không thành phép trừ."},{"id":"m1-32","ch":1,"topic":"Lũy thừa","q":"Công thức của lũy thừa với số mũ nguyên âm (x ≠ 0) là công thức nào?","options":["x⁻ⁿ = −xⁿ","x⁻ⁿ = 1/xⁿ","x⁻ⁿ = −1/xⁿ","x⁻ⁿ = xⁿ"],"correct":1,"answer":"x⁻ⁿ = 1/xⁿ","explanation":"🔑 x⁻ⁿ = 1/xⁿ: dấu trừ ở số mũ là lật xuống mẫu, không làm kết quả âm.<br>✗ −xⁿ: dấu trừ nhảy ra trước cơ số.<br>✗ −1/xⁿ: thừa dấu âm, 2⁻² = 1/4.<br>✗ xⁿ: bỏ mất dấu trừ ở số mũ."},{"id":"m1-33","ch":1,"topic":"Lũy thừa","q":"Công thức x⁰ = 1 đúng với điều kiện nào?","options":["x > 0","x ∈ ℤ","Mọi giá trị của x","x ≠ 0"],"correct":3,"answer":"x ≠ 0","explanation":"🔑 x⁰ = 1 chỉ đúng khi x ≠ 0; riêng 0⁰ không xác định.<br>✗ x > 0: cơ số âm vẫn được, (−3)⁰ = 1.<br>✗ x ∈ ℤ: số hữu tỉ vẫn được, (2/5)⁰ = 1.<br>✗ Mọi giá trị của x: bỏ sót x = 0."},{"id":"m1-34","ch":1,"topic":"Lũy thừa","q":"Công thức (x/y)ⁿ = xⁿ/yⁿ cần thêm điều kiện nào?","options":["x ≠ 0","n > 0","y ≠ 0","x > y"],"correct":2,"answer":"y ≠ 0","explanation":"🔑 Lũy thừa của một thương bằng thương các lũy thừa, và mẫu số luôn phải khác 0 nên cần y ≠ 0. Ví dụ: (2/3)² = 2²/3² = 4/9.<br>✗ x ≠ 0: tử được phép bằng 0, chẳng hạn (0/5)³ = 0.<br>✗ n > 0: với n = 0 công thức vẫn đúng, vì theo quy ước x⁰ = 1 (x ≠ 0) nên hai vế đều bằng 1.<br>✗ x > y: so sánh tử với mẫu không liên quan đến điều kiện của công thức."},{"id":"m1-35","ch":1,"topic":"Lũy thừa","q":"Công thức x⁻ⁿ = 1/xⁿ (với n là số tự nhiên dương) đòi hỏi thêm điều kiện nào?","options":["x ≠ 0","x > 0","x ∈ ℤ","n là số chẵn"],"correct":0,"answer":"x ≠ 0","explanation":"🔑 SGK định nghĩa x⁻ⁿ = 1/xⁿ với n là số tự nhiên dương, x ≠ 0 — vì xⁿ nằm dưới mẫu nên cơ số phải khác 0. Ví dụ: 1/100 = 1/10² = 10⁻².<br>✗ x > 0: cơ số âm vẫn được, (−2)⁻² = 1/(−2)² = 1/4.<br>✗ x ∈ ℤ: cơ số là số hữu tỉ khác 0 đều được, chẳng hạn x = 1/2.<br>✗ n là số chẵn: mũ lẻ vẫn đúng, 2⁻³ = 1/2³ = 1/8."},{"id":"m1-36","ch":1,"topic":"Lũy thừa","q":"Công thức nào dưới đây SAI?","options":["xᵐ · xⁿ = xᵐ⁺ⁿ","xᵐ + xⁿ = xᵐ⁺ⁿ","(xᵐ)ⁿ = xᵐⁿ","xᵐ : xⁿ = xᵐ⁻ⁿ"],"correct":1,"answer":"xᵐ + xⁿ = xᵐ⁺ⁿ","explanation":"🔑 Không có công thức cho phép CỘNG: 2² + 2³ = 12, còn 2⁵ = 32.<br>✗ xᵐ · xⁿ = xᵐ⁺ⁿ: đúng, nhân thì cộng mũ.<br>✗ (xᵐ)ⁿ = xᵐⁿ: đúng, mũ của mũ thì nhân.<br>✗ xᵐ : xⁿ = xᵐ⁻ⁿ: đúng, chia thì trừ mũ."},{"id":"m1-37","ch":1,"topic":"Lũy thừa","q":"Viết 1/x⁵ dưới dạng một lũy thừa (x ≠ 0) thì được kết quả nào?","options":["x⁵","−x⁵","(1/x)⁻⁵","x⁻⁵"],"correct":3,"answer":"x⁻⁵","explanation":"🔑 x⁻ⁿ = 1/xⁿ, nên 1/x⁵ = x⁻⁵.<br>✗ x⁵: quên dấu trừ.<br>✗ −x⁵: dấu trừ phải ở số mũ.<br>✗ (1/x)⁻⁵: đảo dấu hai lần, thành x⁵."},{"id":"m1-38","ch":1,"topic":"Lũy thừa","q":"Biểu thức (x · y)³ bằng bao nhiêu?","options":["3xy","x³ + y³","x³y³","xy³"],"correct":2,"answer":"x³y³","explanation":"🔑 (xy)ⁿ = xⁿyⁿ, nên (xy)³ = x³y³.<br>✗ 3xy: nhân với 3, không lên mũ 3.<br>✗ x³ + y³: tích không tách thành tổng.<br>✗ xy³: quên nâng lũy thừa cho x."},{"id":"m1-39","ch":1,"topic":"Lũy thừa","q":"Biểu thức (x⁴)³ bằng bao nhiêu?","options":["x¹²","x⁷","x⁶⁴","x⁴"],"correct":0,"answer":"x¹²","explanation":"🔑 (xᵐ)ⁿ = xᵐⁿ, lấy 4 · 3 = 12 nên (x⁴)³ = x¹².<br>✗ x⁷: cộng mũ 4 + 3, đó là phép nhân.<br>✗ x⁶⁴: lấy 4³ = 64, nhầm cơ số với mũ.<br>✗ x⁴: bỏ quên số mũ 3 ngoài ngoặc."},{"id":"m1-40","ch":1,"topic":"Lũy thừa","q":"Biểu thức x⁵ : x² bằng bao nhiêu (x ≠ 0)?","options":["x⁷","x³","x¹⁰","x⁻³"],"correct":1,"answer":"x³","explanation":"🔑 Chia thì trừ số mũ: x⁵ : x² = x⁵⁻² = x³.<br>✗ x⁷: cộng mũ, đó là phép nhân.<br>✗ x¹⁰: nhân mũ, đó là (xᵐ)ⁿ.<br>✗ x⁻³: trừ ngược thứ tự (2 − 5)."},{"id":"m1-41","ch":1,"topic":"Lũy thừa","q":"Viết kết quả của phép tính (−2)³ · (−2)⁴ dưới dạng một lũy thừa thì được kết quả nào?","options":["(−2)⁷","(−2)¹²","4⁷","(−2)¹"],"correct":0,"answer":"(−2)⁷","explanation":"🔑 Khi nhân hai lũy thừa cùng cơ số, ta giữ nguyên cơ số và cộng hai số mũ: (−2)³ · (−2)⁴ = (−2)³⁺⁴ = (−2)⁷.<br>✗ (−2)¹²: nhân hai số mũ 3 · 4, đó là công thức (xᵐ)ⁿ = xᵐⁿ.<br>✗ 4⁷: nhân cả cơ số; cơ số phải giữ nguyên.<br>✗ (−2)¹: trừ số mũ 4 − 3, đó là phép chia hai lũy thừa."},{"id":"m1-42","ch":1,"topic":"Lũy thừa","q":"Biểu thức (2/3)⁴ bằng bao nhiêu?","options":["2/3⁴","2⁴/3","2⁴/3⁴","(2·4)/(3·4)"],"correct":2,"answer":"2⁴/3⁴","explanation":"🔑 (x/y)ⁿ = xⁿ/yⁿ, nên (2/3)⁴ = 2⁴/3⁴ = 16/81.<br>✗ 2/3⁴: quên nâng lũy thừa cho tử.<br>✗ 2⁴/3: quên nâng lũy thừa cho mẫu.<br>✗ (2·4)/(3·4): nhân với 4, không lên mũ."},{"id":"m1-43","ch":1,"topic":"Áp dụng lũy thừa","q":"Kết quả của 2³ · 2⁴ là gì?","options":["2⁷","2¹²","4⁷","2⁻¹"],"correct":0,"answer":"2⁷","explanation":"🔑 Cùng cơ số 2, nhân thì cộng mũ: 2³ · 2⁴ = 2⁷ = 128.<br>✗ 2¹²: nhân mũ 3 · 4, đó là (xᵐ)ⁿ.<br>✗ 4⁷: nhân cả cơ số; cơ số giữ nguyên.<br>✗ 2⁻¹: trừ mũ 3 − 4, đó là phép chia."},{"id":"m1-44","ch":1,"topic":"Áp dụng lũy thừa","q":"Kết quả của 5⁶ : 5⁴ là gì?","options":["5¹⁰","5²","5²⁴","5⁻²"],"correct":1,"answer":"5²","explanation":"🔑 Chia thì trừ mũ: 5⁶ : 5⁴ = 5⁶⁻⁴ = 5² = 25.<br>✗ 5¹⁰: cộng mũ, đó là phép nhân.<br>✗ 5²⁴: nhân mũ 6 · 4, đó là (xᵐ)ⁿ.<br>✗ 5⁻²: trừ ngược thứ tự (4 − 6)."},{"id":"m1-45","ch":1,"topic":"Áp dụng lũy thừa","q":"Giá trị của (−1/2)³ là bao nhiêu?","options":["1/8","−3/8","−1/6","−1/8"],"correct":3,"answer":"−1/8","explanation":"🔑 (−1/2)³ = (−1)³/2³ = −1/8; mũ lẻ giữ nguyên dấu âm.<br>✗ 1/8: quên dấu âm, mũ chẵn mới dương.<br>✗ −3/8: nhân tử với 3 thay vì mũ 3.<br>✗ −1/6: lấy 2 · 3 thay vì 2³ = 8."},{"id":"m1-46","ch":1,"topic":"Áp dụng lũy thừa","q":"Giá trị của 3⁻² là bao nhiêu?","options":["−9","−1/9","1/9","1/6"],"correct":2,"answer":"1/9","explanation":"🔑 x⁻ⁿ = 1/xⁿ, nên 3⁻² = 1/3² = 1/9.<br>✗ −9: nhầm dấu trừ ở mũ thành giá trị âm.<br>✗ −1/9: thừa dấu âm, kết quả vẫn dương.<br>✗ 1/6: lấy 3 · 2 thay vì 3² = 9."},{"id":"m1-47","ch":1,"topic":"Áp dụng chuyển vế","q":"Tìm x biết x + 1/2 = 3/2. Giá trị của x là bao nhiêu?","options":["1","2","−1","3/4"],"correct":0,"answer":"1","explanation":"🔑 Chuyển 1/2 sang phải và đổi dấu: x = 3/2 − 1/2 = 1.<br>✗ 2: lấy 3/2 + 1/2, quên đổi dấu.<br>✗ −1: lấy 1/2 − 3/2, đảo thứ tự.<br>✗ 3/4: nhân 3/2 · 1/2 thay vì trừ."},{"id":"m1-48","ch":1,"topic":"Áp dụng chuyển vế","q":"Tìm x biết x − 1/3 = 1/3. Giá trị của x là bao nhiêu?","options":["0","2/3","−2/3","1/9"],"correct":1,"answer":"2/3","explanation":"🔑 A − B = C ⇒ A = C + B, nên x = 1/3 + 1/3 = 2/3.<br>✗ 0: lấy 1/3 − 1/3, quên đổi dấu.<br>✗ −2/3: cộng đúng nhưng thêm dấu âm.<br>✗ 1/9: nhân 1/3 · 1/3 thay vì cộng."},{"id":"m1-49","ch":1,"topic":"Áp dụng lũy thừa","q":"Biểu thức (3 · 4)² bằng biểu thức nào?","options":["3² + 4²","3 · 4²","(3 + 4)²","3² · 4²"],"correct":3,"answer":"3² · 4²","explanation":"🔑 (xy)ⁿ = xⁿyⁿ, nên (3 · 4)² = 3² · 4² = 144.<br>✗ 3² + 4²: tích không tách thành tổng.<br>✗ 3 · 4² = 48: quên nâng mũ cho số 3.<br>✗ (3 + 4)²: đổi dấu nhân thành dấu cộng."},{"id":"m1-50","ch":1,"topic":"Áp dụng lũy thừa","q":"Rút gọn (x³)² : x⁴ (với x ≠ 0) ta được kết quả nào?","options":["x¹⁰","x¹","x²","x⁻²"],"correct":2,"answer":"x²","explanation":"🔑 (x³)² = x⁶ (vì 3 · 2 = 6), rồi x⁶ : x⁴ = x².<br>✗ x¹⁰: cộng mũ 6 + 4 thay vì trừ.<br>✗ x¹: tính nhầm (x³)² = x⁵ rồi mới chia.<br>✗ x⁻²: trừ ngược thứ tự (4 − 6)."},{"id":"m1-c1","ch":1,"topic":"Lũy thừa của số hữu tỉ","type":"calc","q":"Viết gọn thành một lũy thừa: 2³ · 2⁴ = ?","answer":"2⁷","accept":[],"keys":["^"],"explanation":"🔑 Nhân hai lũy thừa CÙNG cơ số thì giữ nguyên cơ số và CỘNG các số mũ: 2³ · 2⁴ = 2³⁺⁴ = 2⁷.<br>✗ 2¹² là nhân hai số mũ — đó là quy tắc của (2³)⁴, không phải 2³ · 2⁴.<br>✗ 4⁷ là nhân luôn cả cơ số — cơ số phải giữ nguyên."},{"id":"m1-c2","ch":1,"topic":"Cộng phân số","type":"calc","q":"Tính rồi rút gọn: 1/2 + 1/4 = ?","answer":"3/4","accept":["0,75"],"keys":[],"explanation":"🔑 Quy đồng mẫu trước rồi mới cộng TỬ, giữ nguyên mẫu: 1/2 = 2/4, nên 2/4 + 1/4 = 3/4.<br>✗ 2/6 là cộng cả tử với tử và mẫu với mẫu — phân số không cộng như thế."},{"id":"m2-1","ch":2,"topic":"Giá trị tuyệt đối","q":"Giá trị tuyệt đối của một số âm bằng gì?","options":["Số đối của nó","Chính nó","Bằng 0","Một số âm"],"correct":0,"answer":"Số đối của nó","explanation":"🔑 Giá trị tuyệt đối của một số âm là số đối của nó. Ví dụ |−2| = 2; |−5,1| = 5,1; |−√2| = √2. (Số đối của a kí hiệu là −a, và số đối của một số âm là một số dương.)<br>✗ Chính nó: đó là quy tắc cho số DƯƠNG, ví dụ |2| = 2; còn |−2| = 2 chứ không phải −2.<br>✗ Bằng 0: chỉ có |0| = 0; một số âm cách gốc O một khoảng lớn hơn 0.<br>✗ Một số âm: giá trị tuyệt đối là khoảng cách từ điểm đó đến gốc O nên không bao giờ âm."},{"id":"m2-2","ch":2,"topic":"Giá trị tuyệt đối","q":"Giá trị tuyệt đối của một số dương bằng gì?","options":["Số đối của nó","Chính nó","Bằng 0","Nhỏ hơn số đó"],"correct":1,"answer":"Chính nó","explanation":"🔑 Giá trị tuyệt đối của một số dương là chính nó. Ví dụ |2| = 2; |5/8| = 5/8.<br>✗ Số đối của nó: đó là quy tắc cho số ÂM, ví dụ |−2| = 2; với số dương thì giữ nguyên: |2| = 2.<br>✗ Bằng 0: chỉ có giá trị tuyệt đối của 0 mới bằng 0; số dương cách gốc O một khoảng đúng bằng chính nó.<br>✗ Nhỏ hơn số đó: |2| = 2, bằng đúng số đó chứ không nhỏ hơn."},{"id":"m2-3","ch":2,"topic":"Giá trị tuyệt đối","q":"Với mọi số thực a, giá trị tuyệt đối |a| luôn thỏa mãn điều kiện nào?","options":["|a| > 0","|a| ≥ 0","|a| ≤ 0","|a| = a"],"correct":1,"answer":"|a| ≥ 0","explanation":"🔑 |a| là khoảng cách tới gốc 0, mà khoảng cách không âm nên |a| ≥ 0.<br>✗ |a| > 0: sai khi a = 0, vì |0| = 0.<br>✗ |a| ≤ 0: sai vì |5| = 5 > 0.<br>✗ |a| = a: chỉ đúng khi a ≥ 0."},{"id":"m2-4","ch":2,"topic":"Giá trị tuyệt đối","q":"Nếu |a| = 0 thì a bằng bao nhiêu?","options":["a là số dương bất kì","a là số âm bất kì","Không tồn tại số a nào","a = 0"],"correct":3,"answer":"a = 0","explanation":"🔑 Giá trị tuyệt đối của 0 là 0, và chỉ điểm 0 cách gốc O một khoảng bằng 0, nên |a| = 0 thì a = 0.<br>✗ a là số dương bất kì: giá trị tuyệt đối của số dương là chính nó, ví dụ |2| = 2 ≠ 0.<br>✗ a là số âm bất kì: giá trị tuyệt đối của số âm là số đối của nó, là một số dương, ví dụ |−2| = 2 ≠ 0.<br>✗ Không tồn tại số a nào: có chứ, a = 0 thỏa mãn vì |0| = 0."},{"id":"m2-5","ch":2,"topic":"Giá trị tuyệt đối","q":"Khẳng định nào sau đây là SAI với mọi số thực a?","options":["|a| ≥ 0","|a| = |−a|","|a| < 0","|0| = 0"],"correct":2,"answer":"|a| < 0","explanation":"🔑 |a| là khoảng cách nên luôn ≥ 0, vậy |a| &lt; 0 là câu SAI.<br>✗ |a| ≥ 0: đúng, không phải câu SAI.<br>✗ |a| = |−a|: đúng, không phải câu SAI.<br>✗ |0| = 0: đúng vì 0 ≥ 0."},{"id":"m2-6","ch":2,"topic":"Giá trị tuyệt đối","q":"Quan hệ nào giữa |a| và |−a| là đúng với mọi số thực a?","options":["|a| = |−a|","|a| = −|−a|","|a| > |−a| khi a > 0","|a| < |−a| khi a < 0"],"correct":0,"answer":"|a| = |−a|","explanation":"🔑 a và −a là hai số đối, cách gốc 0 bằng nhau, nên |a| = |−a|.<br>✗ |a| = −|−a|: vế phải ≤ 0, vế trái ≥ 0.<br>✗ a > 0: cả hai đều bằng a, không hơn kém.<br>✗ a &lt; 0: cả hai đều bằng −a, vẫn bằng nhau."},{"id":"m2-7","ch":2,"topic":"Giá trị tuyệt đối","q":"Nếu |x| = 5 thì x có thể nhận giá trị nào?","options":["Chỉ x = 5","Chỉ x = −5","x = 25","x = 5 hoặc x = −5"],"correct":3,"answer":"x = 5 hoặc x = −5","explanation":"🔑 Đúng hai số cách gốc 0 là 5 đơn vị: x = 5 hoặc x = −5.<br>✗ Chỉ x = 5: bỏ sót nghiệm âm.<br>✗ Chỉ x = −5: bỏ sót nghiệm dương.<br>✗ x = 25: nhầm sang phép bình phương."},{"id":"m2-8","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a < 0, kết quả |a| là số như thế nào?","options":["Là số âm","Là số dương","Bằng 0","Bằng chính a"],"correct":1,"answer":"Là số dương","explanation":"🔑 a là số âm nên |a| là số đối của nó, mà số đối của một số âm là số DƯƠNG. Ví dụ a = −3 thì |−3| = 3 > 0.<br>✗ Số âm: |a| ≥ 0, không bao giờ âm.<br>✗ Bằng 0: chỉ khi a = 0, mà a &lt; 0.<br>✗ Bằng a: chỉ đúng khi a ≥ 0."},{"id":"m2-9","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a > 0, biểu thức |−a| bằng gì?","options":["|−a| = −a","|−a| = 0","|−a| = a","|−a| = a²"],"correct":2,"answer":"|−a| = a","explanation":"🔑 Hai số đối nhau thì có giá trị tuyệt đối bằng nhau, nên |−a| = |a| = a (a là số dương nên giá trị tuyệt đối của nó là chính nó). Ví dụ a = 3: |−3| = |3| = 3.<br>✗ |−a| = −a: −a là số đối của số dương a nên là số âm, mà giá trị tuyệt đối không bao giờ âm; |−3| = 3 chứ không phải −3.<br>✗ |−a| = 0: chỉ có |0| = 0, mà đề cho a > 0.<br>✗ |−a| = a²: nhầm với bình phương; |−3| = 3 chứ không phải 9."},{"id":"m2-10","ch":2,"topic":"Giá trị tuyệt đối","q":"Trên trục số, |a| biểu diễn điều gì?","options":["Khoảng cách từ điểm a đến gốc 0","Vị trí của điểm a so với điểm 1","Số đối của a trong mọi trường hợp","Bình phương của a"],"correct":0,"answer":"Khoảng cách từ điểm a đến gốc 0","explanation":"🔑 |a| là khoảng cách từ điểm a đến gốc 0, vì thế |a| luôn ≥ 0.<br>✗ So với điểm 1: |a| luôn so với gốc 0.<br>✗ Số đối: chỉ khi a là số âm thì |a| mới bằng số đối của a; với a dương thì |a| là chính a.<br>✗ Bình phương: |−3| = 3 còn (−3)² = 9."},{"id":"m2-11","ch":2,"topic":"Giá trị tuyệt đối","q":"Có bao nhiêu số x thỏa mãn |x| = −3?","options":["Một số","Hai số","Vô số","Không có số nào"],"correct":3,"answer":"Không có số nào","explanation":"🔑 |x| ≥ 0 với mọi x nên |x| = −3 vô nghiệm.<br>✗ Một số: không có nổi một số nào.<br>✗ Hai số: đó là đáp án của |x| = 3.<br>✗ Vô số: tập nghiệm rỗng mà."},{"id":"m2-12","ch":2,"topic":"Giá trị tuyệt đối","q":"Bạn Minh viết |−2,5| = −2,5. Khẳng định của Minh đúng hay sai?","options":["Sai, vì giá trị tuyệt đối của số âm là số đối của nó: |−2,5| = 2,5","Đúng, vì −2,5 là số âm nên giá trị tuyệt đối cũng âm","Sai, vì |−2,5| = 0","Đúng, vì giá trị tuyệt đối giữ nguyên số đã cho"],"correct":0,"answer":"Sai, vì giá trị tuyệt đối của số âm là số đối của nó: |−2,5| = 2,5","explanation":"🔑 Minh viết sai. Giá trị tuyệt đối của một số âm là số đối của nó, nên |−2,5| = 2,5. Giá trị tuyệt đối là khoảng cách từ điểm đó đến gốc O nên không bao giờ âm.<br>✗ Đúng, vì −2,5 là số âm nên giá trị tuyệt đối cũng âm: khoảng cách không thể âm; điểm −2,5 cách gốc O đúng 2,5 đơn vị.<br>✗ Sai, vì |−2,5| = 0: chỉ có |0| = 0; ở đây |−2,5| = 2,5.<br>✗ Đúng, vì giá trị tuyệt đối giữ nguyên số đã cho: chỉ số dương và số 0 mới có giá trị tuyệt đối là chính nó."},{"id":"m2-13","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a < 0, biểu thức |a| + a bằng bao nhiêu?","options":["0","2a","−2a","a"],"correct":0,"answer":"0","explanation":"🔑 a là số âm nên giá trị tuyệt đối của a là số đối của nó; mà tổng của một số với số đối của nó bằng 0, vậy |a| + a = 0. Ví dụ a = −3: |−3| + (−3) = 3 − 3 = 0.<br>✗ 2a: lấy nhầm giá trị tuyệt đối của số âm bằng chính nó; với a = −3 thì kết quả là 0 chứ không phải −6.<br>✗ −2a: đó là kết quả của |a| − a; với a = −3: |−3| − (−3) = 3 + 3 = 6.<br>✗ a: bỏ quên mất |a|; với a = −3: |−3| + (−3) = 0 chứ không phải −3."},{"id":"m2-14","ch":2,"topic":"Giá trị tuyệt đối","q":"Giá trị nhỏ nhất của biểu thức |a| là bao nhiêu và đạt được khi nào?","options":["Nhỏ nhất bằng 1, khi a = 1","Không có giá trị nhỏ nhất","Nhỏ nhất bằng 0, khi a = 0","Nhỏ nhất bằng −1, khi a = −1"],"correct":2,"answer":"Nhỏ nhất bằng 0, khi a = 0","explanation":"🔑 |a| ≥ 0 và dấu bằng chỉ khi a = 0, nên nhỏ nhất là 0 tại a = 0.<br>✗ Bằng 1: |0,5| = 0,5 còn nhỏ hơn.<br>✗ Không có: |a| bị chặn dưới bởi 0.<br>✗ Bằng −1: |a| không bao giờ âm."},{"id":"m2-15","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a ≠ 0, khẳng định nào về |a| là đúng?","options":["|a| luôn bằng a","|a| luôn là số dương","|a| có thể bằng 0","|a| luôn cùng dấu với a"],"correct":1,"answer":"|a| luôn là số dương","explanation":"🔑 a ≠ 0 nên điểm a cách gốc O một khoảng khác 0, vậy |a| là số dương. Ví dụ |2| = 2 > 0 và |−2| = 2 > 0.<br>✗ |a| luôn bằng a: sai với số âm — giá trị tuyệt đối của số âm là số đối của nó, ví dụ |−4| = 4 ≠ −4.<br>✗ |a| có thể bằng 0: chỉ có |0| = 0, mà đề cho a ≠ 0.<br>✗ |a| luôn cùng dấu với a: |−2| = 2 là số dương trong khi −2 là số âm."},{"id":"m2-16","ch":2,"topic":"Giá trị tuyệt đối","q":"Đẳng thức |a| = a xảy ra khi nào?","options":["Khi a < 0","Với mọi số thực a","Chỉ khi a = 0","Khi a ≥ 0"],"correct":3,"answer":"Khi a ≥ 0","explanation":"🔑 Giá trị tuyệt đối của một số dương là chính nó (|2| = 2) và giá trị tuyệt đối của 0 là 0, nên |a| = a đúng với mọi a ≥ 0.<br>✗ Khi a &lt; 0: giá trị tuyệt đối của số âm là số đối của nó, ví dụ |−4| = 4 ≠ −4, nên đẳng thức không xảy ra.<br>✗ Với mọi số thực a: sai với số âm — giống bạn Minh trong SGK viết |−2,5| = −2,5 là viết sai.<br>✗ Chỉ khi a = 0: mọi số dương cũng thỏa mãn, ví dụ |2| = 2."},{"id":"m2-17","ch":2,"topic":"Căn bậc hai số học","q":"Định nghĩa nào đúng cho x = √a (với a ≥ 0)?","options":["x ≤ 0 và x² = a","x ≥ 0 và x² = a","x ≥ 0 và x = a²","x là số bất kì có x² = a"],"correct":1,"answer":"x ≥ 0 và x² = a","explanation":"🔑 x = √a ⇔ x ≥ 0 và x² = a, tức căn số học là số KHÔNG ÂM.<br>✗ x ≤ 0: căn số học không bao giờ âm.<br>✗ x = a²: nhầm căn với bình phương, √9 = 3.<br>✗ x bất kì: −3 thỏa x² = 9 mà √9 = 3."},{"id":"m2-18","ch":2,"topic":"Căn bậc hai số học","q":"Tính √(21,5²).","options":["21,5","−21,5","462,25","√21,5"],"correct":0,"answer":"21,5","explanation":"🔑 Vì 21,5 > 0 nên √(21,5²) = 21,5: căn bậc hai số học của 21,5² là số không âm có bình phương bằng 21,5², số đó chính là 21,5. SGK làm tương tự: √(191²) = 191.<br>✗ −21,5: căn bậc hai số học không bao giờ là số âm.<br>✗ 462,25: đó là 21,5², tức số nằm dưới dấu căn, chưa lấy căn.<br>✗ √21,5: nhầm bước; √(21,5²) = 21,5 còn √21,5 ≈ 4,64, hai số khác nhau."},{"id":"m2-19","ch":2,"topic":"Căn bậc hai số học","q":"Biểu thức √a có nghĩa (xác định được) khi nào?","options":["Khi a > 0","Với mọi số thực a","Khi a ≥ 0","Khi a ≤ 0"],"correct":2,"answer":"Khi a ≥ 0","explanation":"🔑 √a chỉ định nghĩa cho số không âm, nên √a có nghĩa khi a ≥ 0.<br>✗ a > 0: thiếu a = 0, mà √0 = 0.<br>✗ Mọi a: √(−4) không có trong ℝ.<br>✗ a ≤ 0: a âm thì căn không xác định."},{"id":"m2-20","ch":2,"topic":"Căn bậc hai số học","q":"Tính √((−5)²).","options":["5","−5","25","−25"],"correct":0,"answer":"5","explanation":"🔑 Tính bình phương trước: (−5)² = 25. Sau đó √25 = 5, vì 5 > 0 và 5² = 25. Vậy √((−5)²) = √25 = 5.<br>✗ −5: căn bậc hai số học là số không âm nên không thể bằng −5.<br>✗ 25: mới dừng ở bước (−5)² = 25, còn phải lấy căn: √25 = 5.<br>✗ −25: (−5)² = 25 là số dương, và √25 = 5."},{"id":"m2-21","ch":2,"topic":"Căn bậc hai số học","q":"Với a là số thực dương, √(a²) bằng gì?","options":["a","−a","a²","√a"],"correct":0,"answer":"a","explanation":"🔑 Vì a là số dương nên √(a²) = a: căn bậc hai số học của a² là số không âm có bình phương bằng a², số đó chính là a. Ví dụ trong SGK: √(3²) = 3 vì 3 > 0.<br>✗ −a: −a là số đối của số dương a nên là số âm, mà căn bậc hai số học không bao giờ âm.<br>✗ a²: đó là số nằm dưới dấu căn; √(3²) = 3 chứ không phải 9.<br>✗ √a: nhầm bước; √(9²) = 9 còn √9 = 3, hai kết quả khác nhau."},{"id":"m2-22","ch":2,"topic":"Căn bậc hai số học","q":"Trong các khẳng định sau, khẳng định nào SAI?","options":["√(3²) = 3","√((−4)²) = −4","√0 = 0","√81 = 9"],"correct":1,"answer":"√((−4)²) = −4","explanation":"🔑 √((−4)²) = √16 = 4, không phải −4, vì căn bậc hai số học luôn là số không âm. Vậy khẳng định √((−4)²) = −4 là SAI.<br>✗ √(3²) = 3: đúng, vì 3 > 0 (Ví dụ trong SGK: √(3²) = 3).<br>✗ √0 = 0: đúng, vì 0 ≥ 0 và 0² = 0.<br>✗ √81 = 9: đúng, vì 9 > 0 và 9² = 81."},{"id":"m2-23","ch":2,"topic":"Căn bậc hai số học","q":"Số nào sau đây KHÔNG thể là kết quả của một căn bậc hai số học?","options":["0","1,5","√2","−4"],"correct":3,"answer":"−4","explanation":"🔑 Căn số học luôn ≥ 0 nên số âm như −4 không thể là kết quả.<br>✗ 0: được chứ, vì √0 = 0.<br>✗ 1,5: được chứ, vì √2,25 = 1,5.<br>✗ √2: được chứ, đó là một số dương."},{"id":"m2-24","ch":2,"topic":"Căn bậc hai số học","q":"Từ x = √a (với a ≥ 0), ta suy ra được đẳng thức nào?","options":["x² = −a","a² = x","x² = a","x = a²"],"correct":2,"answer":"x² = a","explanation":"🔑 x = √a ⇔ x ≥ 0 và x² = a, nên bình phương trả lại số dưới căn.<br>✗ x² = −a: x² ≥ 0 còn −a ≤ 0.<br>✗ a² = x: đảo vai trò, √9 = 3 mà 9² = 81.<br>✗ x = a²: nhầm căn thành bình phương."},{"id":"m2-25","ch":2,"topic":"Căn bậc hai số học","q":"Vì sao √(−9) không có nghĩa trong tập số thực?","options":["Vì −9 không phải số nguyên","Vì không có số thực nào bình phương bằng −9","Vì −9 là số vô tỉ","Vì √(−9) = −3"],"correct":1,"answer":"Vì không có số thực nào bình phương bằng −9","explanation":"🔑 Mọi x² đều ≥ 0 nên không có x nào để x² = −9; √a đòi hỏi a ≥ 0.<br>✗ Số nguyên: −9 vẫn là số nguyên mà.<br>✗ Số vô tỉ: −9 là số hữu tỉ.<br>✗ √(−9) = −3: (−3)² = 9, không phải −9."},{"id":"m2-26","ch":2,"topic":"Căn bậc hai số học","q":"Cả 6 và −6 đều có bình phương bằng 36. Vậy √36 bằng bao nhiêu?","options":["6","−6","6 hoặc −6","18"],"correct":0,"answer":"6","explanation":"🔑 Căn bậc hai số học chỉ lấy giá trị KHÔNG ÂM, nên √36 = 6.<br>✗ −6: số âm nên bị loại.<br>✗ 6 hoặc −6: đó là đáp án của x² = 36.<br>✗ 18: lấy 36 chia 2, đâu phải căn."},{"id":"m2-27","ch":2,"topic":"Căn bậc hai số học","q":"Nếu a ≥ 0 thì bình phương của căn, tức (√a)², cho kết quả nào?","options":["−a","√a","a","a²"],"correct":2,"answer":"a","explanation":"🔑 √a là số có bình phương bằng a, nên (√a)² = a với mọi a ≥ 0.<br>✗ −a: âm khi a > 0, mà (√a)² ≥ 0.<br>✗ √a: quên phép bình phương ở ngoài.<br>✗ a²: bình phương thêm một lần nữa."},{"id":"m2-28","ch":2,"topic":"Căn bậc hai số học","q":"Tính √((−7)²).","options":["−7","49","−49","7"],"correct":3,"answer":"7","explanation":"🔑 Tính trong ngoặc trước: (−7)² = 49, rồi √49 = 7 vì 7 ≥ 0 và 7² = 49. Vậy √((−7)²) = 7.<br>✗ −7: căn bậc hai số học không bao giờ là số âm; cứ tính (−7)² = 49 rồi lấy √49 sẽ ra 7.<br>✗ 49: mới bình phương xong, chưa lấy căn.<br>✗ −49: vừa sai dấu vừa chưa lấy căn."},{"id":"m2-29","ch":2,"topic":"Căn bậc hai số học","q":"Bạn An viết √((−3)²) = −3. Bạn ấy viết đúng hay sai?","options":["Sai, vì (−3)² = 9 và √9 = 3","Đúng, vì dấu căn và bình phương triệt tiêu nhau","Sai, vì √((−3)²) phải bằng 9","Đúng, vì kết quả phải cùng dấu với số ban đầu"],"correct":0,"answer":"Sai, vì (−3)² = 9 và √9 = 3","explanation":"🔑 Tính cụ thể: (−3)² = 9, mà √9 = 3 vì 3 ≥ 0 và 3² = 9. Căn bậc hai số học không bao giờ là số âm, nên viết √((−3)²) = −3 là sai.<br>✗ Đúng, vì dấu căn và bình phương triệt tiêu nhau: điều đó chỉ đúng với số dương, ví dụ √(3²) = 3; với −3 phải tính (−3)² = 9 trước rồi lấy √9 = 3.<br>✗ Sai, vì √((−3)²) phải bằng 9: 9 mới là (−3)², còn phải lấy căn nữa: √9 = 3.<br>✗ Đúng, vì kết quả phải cùng dấu với số ban đầu: căn bậc hai số học luôn không âm, ở đây √9 = 3 là số dương."},{"id":"m2-30","ch":2,"topic":"Căn bậc hai số học","q":"Điều kiện nào phải kèm theo để viết đúng định nghĩa x = √a?","options":["a ≥ 0 và x ≥ 0","a ≤ 0 và x ≥ 0","a ≥ 0 và x ≤ 0","a và x là số bất kì"],"correct":0,"answer":"a ≥ 0 và x ≥ 0","explanation":"🔑 Theo định nghĩa trong sách: căn bậc hai số học của một số a KHÔNG ÂM, kí hiệu là √a, là số x không âm sao cho x² = a. Vậy cần a ≥ 0 và x ≥ 0, ví dụ √16 = 4 vì 4 ≥ 0 và 4² = 16.<br>✗ a ≤ 0 và x ≥ 0: số dưới căn phải không âm, không có căn bậc hai của số âm.<br>✗ a ≥ 0 và x ≤ 0: căn bậc hai số học là số không âm, không thể đòi x ≤ 0.<br>✗ a và x là số bất kì: thế thì √9 = −3 cũng đúng, trái với định nghĩa."},{"id":"m2-31","ch":2,"topic":"Số thực và số thập phân","q":"Số thập phân hữu hạn và số thập phân vô hạn tuần hoàn thuộc tập hợp số nào?","options":["Tập số vô tỉ","Tập số nguyên ℤ","Không thuộc tập hợp nào","Tập số hữu tỉ ℚ"],"correct":3,"answer":"Tập số hữu tỉ ℚ","explanation":"🔑 Số thập phân hữu hạn hay vô hạn tuần hoàn đều viết được dưới dạng phân số, nên là số hữu tỉ, thuộc ℚ. Ví dụ 0,5 = 1/2; 0,(3) = 1/3.<br>✗ Tập số vô tỉ: chỉ gồm các số thập phân vô hạn KHÔNG tuần hoàn.<br>✗ Tập số nguyên ℤ: 0,5 đâu phải số nguyên.<br>✗ Không thuộc tập hợp nào: chúng thuộc ℚ mà."},{"id":"m2-32","ch":2,"topic":"Số thực và số thập phân","q":"Số thập phân vô hạn không tuần hoàn được gọi là gì?","options":["Số hữu tỉ","Số nguyên","Số vô tỉ","Số tự nhiên"],"correct":2,"answer":"Số vô tỉ","explanation":"🔑 Số vô tỉ là số viết được dưới dạng số thập phân vô hạn không tuần hoàn, ví dụ √2 = 1,4142135... không dừng và không có chu kì.<br>✗ Số hữu tỉ: viết được dưới dạng thập phân hữu hạn hoặc vô hạn TUẦN HOÀN.<br>✗ Số nguyên: không có phần thập phân kéo dài mãi.<br>✗ Số tự nhiên: chỉ là 0; 1; 2; ..."},{"id":"m2-33","ch":2,"topic":"Số thực và số thập phân","q":"Tập hợp số thực ℝ gồm những số nào?","options":["Số hữu tỉ và số vô tỉ","Chỉ các số hữu tỉ","Chỉ các số vô tỉ","Chỉ các số nguyên và số thập phân hữu hạn"],"correct":0,"answer":"Số hữu tỉ và số vô tỉ","explanation":"🔑 Số hữu tỉ và số vô tỉ được gọi chung là số thực; tập hợp các số thực kí hiệu là ℝ. Ví dụ 3/4 là số hữu tỉ, √2 là số vô tỉ, cả hai đều là số thực.<br>✗ Chỉ các số hữu tỉ: thiếu các số vô tỉ như √2 và π.<br>✗ Chỉ các số vô tỉ: thiếu các số hữu tỉ như 0,5 và 1/3.<br>✗ Chỉ các số nguyên và số thập phân hữu hạn: còn thiếu số thập phân vô hạn tuần hoàn như 0,(3) và số vô tỉ như √2."},{"id":"m2-34","ch":2,"topic":"Số thực và số thập phân","q":"Một số vừa là số hữu tỉ vừa là số vô tỉ. Khẳng định này đúng hay sai?","options":["Đúng, vì cả hai loại đều là số thực","Sai, vì không có số nào vừa hữu tỉ vừa vô tỉ","Đúng, với các số thập phân vô hạn","Sai, vì số vô tỉ không phải là số thực"],"correct":1,"answer":"Sai, vì không có số nào vừa hữu tỉ vừa vô tỉ","explanation":"🔑 Mỗi số thập phân hoặc là hữu hạn hay vô hạn tuần hoàn (số hữu tỉ), hoặc là vô hạn không tuần hoàn (số vô tỉ), không thể vừa thế này vừa thế kia. Ví dụ 0,(3) là hữu tỉ, còn √2 = 1,4142... là vô tỉ.<br>✗ Đúng, vì cả hai loại đều là số thực: cùng được gọi chung là số thực không có nghĩa là trùng nhau.<br>✗ Đúng, với các số thập phân vô hạn: vô hạn tuần hoàn là hữu tỉ, vô hạn không tuần hoàn là vô tỉ, vẫn chỉ thuộc một loại.<br>✗ Sai, vì số vô tỉ không phải là số thực: lí do này sai, số vô tỉ vẫn là số thực."},{"id":"m2-35","ch":2,"topic":"Số thực và số thập phân","q":"Số 0,333... (chữ số 3 lặp lại mãi) thuộc những tập hợp nào?","options":["Chỉ thuộc 𝕀","Không thuộc ℝ","Thuộc ℚ và thuộc ℝ","Chỉ thuộc ℤ"],"correct":2,"answer":"Thuộc ℚ và thuộc ℝ","explanation":"🔑 0,333... tuần hoàn chu kì 3 nên bằng 1/3: số hữu tỉ, mà ℚ nằm trong ℝ.<br>✗ Chỉ 𝕀: nó có nhóm chữ số lặp lại.<br>✗ Ngoài ℝ: hữu tỉ thì luôn là số thực.<br>✗ Chỉ ℤ: 1/3 không phải số nguyên."},{"id":"m2-36","ch":2,"topic":"Số thực và số thập phân","q":"Số π = 3,141592... là loại số nào?","options":["Số hữu tỉ vì viết được thành phân số","Số thập phân hữu hạn","Số thập phân vô hạn tuần hoàn","Số vô tỉ vì thập phân vô hạn không tuần hoàn"],"correct":3,"answer":"Số vô tỉ vì thập phân vô hạn không tuần hoàn","explanation":"🔑 Phần thập phân của π vô hạn mà không lặp chu kì, nên π là số vô tỉ.<br>✗ Hữu tỉ: π không viết được thành phân số.<br>✗ Hữu hạn: π không dừng lại bao giờ.<br>✗ Tuần hoàn: π không có chu kì lặp."},{"id":"m2-37","ch":2,"topic":"Số thực và số thập phân","q":"Khẳng định nào sau đây là đúng?","options":["Mọi số thực đều là số hữu tỉ","Mọi số hữu tỉ đều là số thực","Mọi số vô tỉ đều là số hữu tỉ","Mọi số thực đều là số vô tỉ"],"correct":1,"answer":"Mọi số hữu tỉ đều là số thực","explanation":"🔑 Số hữu tỉ và số vô tỉ được gọi chung là số thực, nên mọi số hữu tỉ đều là số thực. Ví dụ 0,5 và 1/3 đều là số thực.<br>✗ Mọi số thực đều là số hữu tỉ: √2 là số thực nhưng là số vô tỉ.<br>✗ Mọi số vô tỉ đều là số hữu tỉ: số vô tỉ như √2 không viết được dưới dạng phân số.<br>✗ Mọi số thực đều là số vô tỉ: 0,5 là số thực nhưng là số hữu tỉ."},{"id":"m2-38","ch":2,"topic":"Số thực và số thập phân","q":"Số 2,5 là số thập phân loại nào?","options":["Thập phân hữu hạn, là số hữu tỉ","Thập phân vô hạn tuần hoàn, là số hữu tỉ","Thập phân vô hạn không tuần hoàn, là số vô tỉ","Không phải số thập phân"],"correct":0,"answer":"Thập phân hữu hạn, là số hữu tỉ","explanation":"🔑 2,5 dừng sau một chữ số nên là hữu hạn, bằng 5/2, tức số hữu tỉ.<br>✗ Vô hạn tuần hoàn: 2,5 đâu kéo dài mãi.<br>✗ Vô tỉ: 2,5 viết được thành phân số.<br>✗ Không phải thập phân: rõ ràng nó là."},{"id":"m2-39","ch":2,"topic":"Số thực và số thập phân","q":"Số 1,2333... có nhóm chữ số 3 lặp lại mãi. Cách gọi đúng cho số này là gì?","options":["Số thập phân hữu hạn","Số thập phân vô hạn không tuần hoàn","Số vô tỉ","Số thập phân vô hạn tuần hoàn"],"correct":3,"answer":"Số thập phân vô hạn tuần hoàn","explanation":"🔑 Kéo dài mãi mà chữ số 3 lặp lại: vô hạn TUẦN HOÀN, viết gọn 1,2(3).<br>✗ Hữu hạn: nó có dừng lại đâu.<br>✗ Không tuần hoàn: chu kì 3 rõ ràng.<br>✗ Vô tỉ: tuần hoàn thì là hữu tỉ."},{"id":"m2-40","ch":2,"topic":"Số thực và số thập phân","q":"Vì sao √2 = 1,414213... là số vô tỉ?","options":["Vì nó lớn hơn 1","Vì nó có dấu căn","Vì phần thập phân vô hạn và không tuần hoàn","Vì nó là số âm"],"correct":2,"answer":"Vì phần thập phân vô hạn và không tuần hoàn","explanation":"🔑 Vô tỉ là khi thập phân vô hạn và KHÔNG tuần hoàn, đúng như √2.<br>✗ Lớn hơn 1: 1,5 cũng vậy mà hữu tỉ.<br>✗ Có dấu căn: √4 = 2 vẫn hữu tỉ.<br>✗ Số âm: √2 là số dương mà."},{"id":"m2-41","ch":2,"topic":"Số thực và số thập phân","q":"Có số nào vừa là số hữu tỉ vừa là số vô tỉ không?","options":["Không có số nào như vậy","Có, đó là các số thập phân vô hạn","Có, đó là số 0","Có, mọi số thực đều như vậy"],"correct":0,"answer":"Không có số nào như vậy","explanation":"🔑 Số hữu tỉ viết được dưới dạng số thập phân hữu hạn hoặc vô hạn tuần hoàn, còn số vô tỉ là số thập phân vô hạn KHÔNG tuần hoàn, nên mỗi số chỉ thuộc đúng một loại. Ví dụ 0,(3) là hữu tỉ, √2 là vô tỉ.<br>✗ Có, đó là các số thập phân vô hạn: tuần hoàn thì hữu tỉ, không tuần hoàn thì vô tỉ, vẫn chỉ một loại.<br>✗ Có, đó là số 0: 0 là số hữu tỉ, không phải số vô tỉ.<br>✗ Có, mọi số thực đều như vậy: mỗi số thực hoặc hữu tỉ hoặc vô tỉ, không bao giờ cả hai."},{"id":"m2-42","ch":2,"topic":"Số thực và số thập phân","q":"Số nào sau đây là số vô tỉ?","options":["0,25","√3","√9","1,5(2)"],"correct":1,"answer":"√3","explanation":"🔑 √3 = 1,7320508... vô hạn và không tuần hoàn nên là số vô tỉ.<br>✗ 0,25: hữu hạn, bằng 1/4, nên hữu tỉ.<br>✗ √9 = 3: là số nguyên, thuộc ℚ.<br>✗ 1,5(2): tuần hoàn nên vẫn hữu tỉ."},{"id":"m2-43","ch":2,"topic":"Áp dụng tính toán","q":"Giá trị của √25 là bao nhiêu?","options":["12,5","5 hoặc −5","5","625"],"correct":2,"answer":"5","explanation":"🔑 √25 = 5 vì 5 ≥ 0 và 5² = 25.<br>✗ 12,5: lấy 25 chia 2, đâu phải căn.<br>✗ 5 hoặc −5: cả hai số này bình phương đều bằng 25, nhưng căn bậc hai số học chỉ lấy số không âm, nên √25 = 5.<br>✗ 625: là 25², làm ngược phép toán."},{"id":"m2-44","ch":2,"topic":"Áp dụng tính toán","q":"Tính |−7|.","options":["−7","0","49","7"],"correct":3,"answer":"7","explanation":"🔑 Giá trị tuyệt đối của một số âm là số đối của nó: số đối của −7 là 7 nên |−7| = 7, giống như |−2| = 2; |−5,1| = 5,1.<br>✗ −7: giá trị tuyệt đối là khoảng cách đến gốc O nên không bao giờ âm; viết |−7| = −7 là sai giống như Minh viết |−2,5| = −2,5.<br>✗ 0: chỉ giá trị tuyệt đối của 0 mới bằng 0.<br>✗ 49: đó là (−7)², không phải |−7|."},{"id":"m2-45","ch":2,"topic":"Áp dụng tính toán","q":"Tính |−3| + √16.","options":["1","7","−7","19"],"correct":1,"answer":"7","explanation":"🔑 |−3| = 3 và √16 = 4, nên 3 + 4 = 7.<br>✗ 1: lấy nhầm |−3| = −3.<br>✗ −7: |a| và √a không bao giờ âm.<br>✗ 19: quên lấy căn của 16."},{"id":"m2-46","ch":2,"topic":"Áp dụng tính toán","q":"Tính |5 − 8|.","options":["3","−3","13","40"],"correct":0,"answer":"3","explanation":"🔑 Tính trong dấu trước: 5 − 8 = −3, mà −3 &lt; 0 nên |−3| = 3.<br>✗ −3: quên bước lấy giá trị tuyệt đối.<br>✗ 13: cộng 5 với 8 thay vì trừ.<br>✗ 40: nhân 5 với 8, sai phép tính."},{"id":"m2-47","ch":2,"topic":"Áp dụng tính toán","q":"Tính √0,25.","options":["0,125","0,0625","0,5","2,5"],"correct":2,"answer":"0,5","explanation":"🔑 √0,25 = 0,5 vì 0,5 ≥ 0 và 0,5² = 0,25.<br>✗ 0,125: lấy 0,25 chia 2, đâu phải căn.<br>✗ 0,0625: là 0,25², làm ngược phép toán.<br>✗ 2,5: sai dấu phẩy, vì 2,5² = 6,25."},{"id":"m2-48","ch":2,"topic":"Áp dụng tính toán","q":"Tính |0| + |−1|.","options":["−1","0","2","1"],"correct":3,"answer":"1","explanation":"🔑 Giá trị tuyệt đối của 0 là 0, còn giá trị tuyệt đối của một số âm là số đối của nó nên |−1| = 1. Vậy |0| + |−1| = 0 + 1 = 1.<br>✗ −1: |−1| là số đối của −1, tức là 1; giá trị tuyệt đối không bao giờ âm.<br>✗ 0: bỏ sót hạng tử |−1| = 1.<br>✗ 2: tính nhầm |0| thành 1, trong khi giá trị tuyệt đối của 0 là 0."},{"id":"m2-49","ch":2,"topic":"Áp dụng tính toán","q":"Tính √81 − |−4|.","options":["13","5","−5","77"],"correct":1,"answer":"5","explanation":"🔑 √81 = 9 vì 9 ≥ 0 và 9² = 81, còn |−4| = 4, nên 9 − 4 = 5.<br>✗ 13: cộng thay vì trừ.<br>✗ −5: trừ ngược, lấy 4 − 9.<br>✗ 77: là 81 − 4, quên lấy căn 81."},{"id":"m2-50","ch":2,"topic":"Áp dụng tính toán","q":"Nếu x² = 49 và x < 0 thì x bằng bao nhiêu?","options":["x = −7","x = 7","x = √49","x = −49"],"correct":0,"answer":"x = −7","explanation":"🔑 Hai số bình phương bằng 49 là 7 và −7; điều kiện x &lt; 0 chọn −7.<br>✗ x = 7: vi phạm điều kiện x &lt; 0.<br>✗ x = √49 = 7: căn số học luôn ≥ 0.<br>✗ x = −49: (−49)² = 2401 ≠ 49."},{"id":"m2-c1","ch":2,"topic":"Căn bậc hai số học","type":"calc","q":"Tìm số x > 0 biết x² = 5. Vậy x = ?","answer":"√5","accept":[],"keys":["√"],"explanation":"🔑 x > 0 và x² = 5 thì x = √5. Vì 5 không phải số chính phương nên căn của nó giữ nguyên dạng √5, không ra số tròn.<br>✗ 2,5 là lấy 5 chia cho 2 — chia đôi không phải là khai căn."},{"id":"m2-c2","ch":2,"topic":"Giá trị tuyệt đối","type":"calc","q":"Rút gọn: √(a²) = ? (với a là số bất kì)","answer":"|a|","accept":[],"keys":["|","a"],"explanation":"🔑 √(a²) = |a|, KHÔNG phải a. Thử a = −3: √((−3)²) = √9 = 3, mà 3 chính là |−3|.<br>✗ a sai ngay khi a âm — căn bậc hai số học không bao giờ cho kết quả âm."},{"id":"m3-1","ch":3,"topic":"Hai góc kề bù","q":"Hai góc kề bù có tổng số đo bằng bao nhiêu?","options":["∠xOz + ∠zOy = 180°","∠xOz + ∠zOy = 90°","∠xOz + ∠zOy = 360°","∠xOz = ∠zOy"],"correct":0,"answer":"∠xOz + ∠zOy = 180°","explanation":"🔑 Hai góc kề bù có tổng số đo bằng <b>180°</b>. Ví dụ: ∠xOz = 60° thì ∠zOy = 180° − 60° = 120°.<br>✗ ∠xOz + ∠zOy = 90°: SGK chỉ nói tổng hai góc kề bù bằng 180°, không có tính chất tổng 90°.<br>✗ ∠xOz + ∠zOy = 360°: 360° là tổng cả bốn góc khi hai đường thẳng cắt nhau (hai cặp kề bù: 180° + 180°), không phải tổng của một cặp kề bù.<br>✗ ∠xOz = ∠zOy: hai góc kề bù chỉ bằng nhau khi mỗi góc là góc vuông 90°, không phải lúc nào cũng vậy."},{"id":"m3-2","ch":3,"topic":"Hai góc kề bù","q":"Cho ∠xOz và ∠zOy là hai góc kề bù, biết ∠xOz = 130°. Số đo ∠zOy bằng bao nhiêu?","options":["∠zOy = 130°","∠zOy = 50°","∠zOy = 230°","∠zOy = 65°"],"correct":1,"answer":"∠zOy = 50°","explanation":"🔑 Kề bù ⇒ ∠zOy = 180° − 130° = <b>50°</b>.<br>✗ 130°: bằng nhau là góc đối đỉnh.<br>✗ 230°: dùng nhầm 360° quanh một điểm.<br>✗ 65°: nửa của 130°, đó là phân giác."},{"id":"m3-3","ch":3,"topic":"Hai góc đối đỉnh","q":"Hai góc đối đỉnh thì có quan hệ gì về số đo?","options":["Tổng số đo bằng 180°","Tổng số đo bằng 90°","Chúng bằng nhau","Góc này bằng một nửa góc kia"],"correct":2,"answer":"Chúng bằng nhau","explanation":"🔑 Hai góc đối đỉnh thì <b>bằng nhau</b>. Ví dụ: hai đường thẳng cắt nhau tạo một góc 40° thì góc đối đỉnh với nó cũng bằng 40°.<br>✗ Tổng số đo bằng 180°: đó là hai góc kề bù (hai góc bù nhau), không phải hai góc đối đỉnh.<br>✗ Tổng số đo bằng 90°: SGK không có tính chất nào như vậy; hai góc đối đỉnh là bằng nhau.<br>✗ Góc này bằng một nửa góc kia: nhầm với tia phân giác chia một góc thành hai góc bằng nhau."},{"id":"m3-4","ch":3,"topic":"Hai góc đối đỉnh","q":"Hai đường thẳng cắt nhau tại O tạo thành bốn góc, trong đó có một góc bằng 40°. Góc đối đỉnh với góc 40° bằng bao nhiêu?","options":["140°","180°","20°","40°"],"correct":3,"answer":"40°","explanation":"🔑 Đối đỉnh thì bằng nhau ⇒ cũng <b>40°</b>.<br>✗ 140°: đó là góc kề bù, 180° − 40°.<br>✗ 180°: đó là góc bẹt, không phải góc này.<br>✗ 20°: nửa của 40°, nhầm phân giác."},{"id":"m3-5","ch":3,"topic":"Hai góc kề bù","q":"Hai đường thẳng cắt nhau tại O, một trong bốn góc tạo thành bằng 35°. Số đo của góc kề bù với góc đó là bao nhiêu?","options":["145°","35°","55°","325°"],"correct":0,"answer":"145°","explanation":"🔑 Hai góc kề bù có tổng số đo bằng 180° ⇒ góc kề bù với góc 35° bằng 180° − 35° = <b>145°</b>.<br>✗ 35°: đó là góc đối đỉnh với góc đã cho (hai góc đối đỉnh thì bằng nhau), không phải góc kề bù.<br>✗ 55°: lấy 90° − 35° là sai, vì tổng hai góc kề bù là 180°, không phải 90°.<br>✗ 325°: lấy 360° − 35° là sai; 360° là tổng cả bốn góc, còn một cặp kề bù chỉ có tổng 180°."},{"id":"m3-6","ch":3,"topic":"Hai góc kề bù","q":"Hai góc kề bù có số đo bằng nhau thì mỗi góc bằng bao nhiêu?","options":["45°","90°","60°","180°"],"correct":1,"answer":"90°","explanation":"🔑 Tổng 180°, chia đôi ⇒ mỗi góc <b>90°</b>.<br>✗ 45°: nhầm tổng là 90° rồi chia 2.<br>✗ 60°: chia 180° cho 3, chỉ có 2 góc.<br>✗ 180°: đó là tổng của cả hai góc."},{"id":"m3-7","ch":3,"topic":"Góc tạo bởi hai đường thẳng cắt nhau","q":"Tổng số đo bốn góc tạo bởi hai đường thẳng cắt nhau tại một điểm bằng bao nhiêu?","options":["180°","90°","360°","720°"],"correct":2,"answer":"360°","explanation":"🔑 Bốn góc chia được thành hai cặp góc kề bù, mỗi cặp có tổng 180° ⇒ tổng bốn góc là 180° + 180° = <b>360°</b>.<br>✗ 180°: chỉ là tổng của một cặp góc kề bù, tức là mới hai trong bốn góc.<br>✗ 90°: đó là số đo của một góc vuông, không phải tổng của bốn góc.<br>✗ 720°: đếm mỗi góc hai lần; 360° + 360° = 720° là sai."},{"id":"m3-8","ch":3,"topic":"Hai góc kề bù","q":"Điều kiện để hai góc ∠xOz và ∠zOy là hai góc kề bù là gì?","options":["Hai góc bằng nhau và có chung đỉnh O","Hai góc có chung đỉnh O và tổng bằng 90°","Hai góc đối đỉnh nhau qua điểm O","Hai góc kề nhau (chung cạnh Oz) và hai tia Ox, Oy đối nhau"],"correct":3,"answer":"Hai góc kề nhau (chung cạnh Oz) và hai tia Ox, Oy đối nhau","explanation":"🔑 Theo SGK: hai góc có một cạnh chung, hai cạnh còn lại là <b>hai tia đối nhau</b> được gọi là hai góc kề bù. Ví dụ: ∠xOz = 120° và ∠zOy = 60° chung cạnh Oz, còn Ox và Oy là hai tia đối nhau.<br>✗ Hai góc bằng nhau và có chung đỉnh O: hai góc kề bù không cần bằng nhau (chúng chỉ bằng nhau khi mỗi góc là 90°).<br>✗ Hai góc có chung đỉnh O và tổng bằng 90°: tổng hai góc kề bù là 180°, không phải 90°.<br>✗ Hai góc đối đỉnh nhau qua điểm O: hai góc đối đỉnh không có cạnh chung nên không kề nhau."},{"id":"m3-9","ch":3,"topic":"Hai góc kề bù","q":"Một góc có số đo 90°. Góc kề bù với nó có số đo bằng bao nhiêu?","options":["90°","0°","180°","270°"],"correct":0,"answer":"90°","explanation":"🔑 180° − 90° = <b>90°</b>, cũng là góc vuông.<br>✗ 0°: 90° − 90°, nhầm tổng là 90°.<br>✗ 180°: đó là tổng của hai góc.<br>✗ 270°: 360° − 90°, nhầm góc quanh điểm."},{"id":"m3-10","ch":3,"topic":"Hai góc đối đỉnh","q":"Khẳng định nào sau đây đúng về hai góc đối đỉnh?","options":["Hai góc bằng nhau thì luôn đối đỉnh với nhau","Hai góc đối đỉnh thì bằng nhau, nhưng hai góc bằng nhau chưa chắc đối đỉnh","Hai góc đối đỉnh thì bù nhau","Hai góc đối đỉnh thì có chung một cạnh"],"correct":1,"answer":"Hai góc đối đỉnh thì bằng nhau, nhưng hai góc bằng nhau chưa chắc đối đỉnh","explanation":"🔑 Đối đỉnh ⇒ bằng nhau, nhưng bằng nhau chưa chắc đối đỉnh.<br>✗ Bằng nhau thì đối đỉnh: đảo mệnh đề.<br>✗ Bù nhau: đó là hai góc kề bù.<br>✗ Chung cạnh: đối đỉnh không chung cạnh."},{"id":"m3-11","ch":3,"topic":"Tia phân giác","q":"Nếu Oz là tia phân giác của ∠xOy thì công thức nào sau đây đúng?","options":["∠xOz + ∠zOy = 180°","∠xOz = ∠zOy = ½∠xOy","∠xOz = 2∠xOy","∠xOz = ∠xOy"],"correct":1,"answer":"∠xOz = ∠zOy = ½∠xOy","explanation":"🔑 Phân giác chia đôi: <b>∠xOz = ∠zOy = ½∠xOy</b>.<br>✗ Tổng 180°: đó là hai góc kề bù.<br>✗ 2∠xOy: ngược chiều, góc con nhỏ hơn.<br>✗ ∠xOz = ∠xOy: Oz trùng tia Oy."},{"id":"m3-12","ch":3,"topic":"Tia phân giác","q":"Cho ∠xOy = 80° và Oz là tia phân giác của ∠xOy. Số đo ∠xOz bằng bao nhiêu?","options":["160°","100°","40°","80°"],"correct":2,"answer":"40°","explanation":"🔑 Phân giác ⇒ ∠xOz = ½ · 80° = <b>40°</b>.<br>✗ 160°: nhân đôi thay vì chia đôi.<br>✗ 100°: 180° − 80°, nhầm kề bù.<br>✗ 80°: giữ góc lớn, quên chia đôi."},{"id":"m3-13","ch":3,"topic":"Tia phân giác","q":"Tia Oz là tia phân giác của ∠xOy và ∠xOz = 35°. Số đo ∠xOy bằng bao nhiêu?","options":["35°","145°","17,5°","70°"],"correct":3,"answer":"70°","explanation":"🔑 Đi ngược: ∠xOy = 2 · 35° = <b>70°</b>.<br>✗ 35°: mới là nửa góc, chưa cả góc.<br>✗ 145°: 180° − 35°, nhầm kề bù.<br>✗ 17,5°: chia đôi tiếp, ngược chiều."},{"id":"m3-14","ch":3,"topic":"Tia phân giác","q":"Tia phân giác của một góc bẹt (180°) chia góc đó thành hai góc, mỗi góc bằng bao nhiêu?","options":["90°","45°","180°","360°"],"correct":0,"answer":"90°","explanation":"🔑 ½ · 180° = <b>90°</b>, tia đó vuông góc với hai cạnh.<br>✗ 45°: chia đôi tới hai lần.<br>✗ 180°: giữ nguyên, quên chia đôi.<br>✗ 360°: nhân đôi thay vì chia đôi."},{"id":"m3-15","ch":3,"topic":"Tia phân giác","q":"Điều kiện nào sau đây khẳng định tia Oz là tia phân giác của ∠xOy?","options":["Oz nằm giữa hai tia Ox, Oy và ∠xOz = ∠zOy","Oz vuông góc với tia Ox","∠xOz + ∠zOy = 180°","Oz là tia đối của tia Ox"],"correct":0,"answer":"Oz nằm giữa hai tia Ox, Oy và ∠xOz = ∠zOy","explanation":"🔑 Phân giác phải <b>nằm giữa</b> và chia góc thành hai phần bằng nhau.<br>✗ Oz ⊥ Ox: chưa chắc chia đôi ∠xOy.<br>✗ Tổng 180°: đó là kề bù, chưa chia đôi.<br>✗ Tia đối Ox: nằm ngoài góc ∠xOy."},{"id":"m3-16","ch":3,"topic":"Tia phân giác","q":"Một góc khác góc bẹt có bao nhiêu tia phân giác?","options":["Vô số tia","Đúng một tia","Hai tia","Không có tia nào"],"correct":1,"answer":"Đúng một tia","explanation":"🔑 Mỗi góc khác góc bẹt có <b>đúng một</b> tia phân giác.<br>✗ Vô số tia: từ đỉnh O kẻ được vô số tia, nhưng chỉ một tia vừa nằm giữa vừa chia góc thành hai phần bằng nhau.<br>✗ Hai tia: chỉ góc bẹt mới có hai tia phân giác (hai tia vuông góc với hai cạnh, ở hai phía); đề đã loại góc bẹt.<br>✗ Không có tia nào: góc nào cũng chia đôi được."},{"id":"m3-17","ch":3,"topic":"Tia phân giác và góc kề bù","q":"Hai góc ∠xOz và ∠zOy kề bù, tia Ot là tia phân giác của ∠xOz. Biết ∠xOz = 100°, số đo ∠tOz bằng bao nhiêu?","options":["80°","100°","50°","40°"],"correct":2,"answer":"50°","explanation":"🔑 Phân giác ⇒ ∠tOz = ½ · 100° = <b>50°</b>.<br>✗ 80°: đó là ∠zOy kề bù, 180° − 100°.<br>✗ 100°: giữ nguyên ∠xOz, quên chia đôi.<br>✗ 40°: chia đôi nhầm góc kề bù 80°."},{"id":"m3-18","ch":3,"topic":"Tia phân giác","q":"Một góc được tia phân giác chia thành hai góc, mỗi góc bằng 25°. Góc ban đầu bằng bao nhiêu?","options":["25°","12,5°","155°","50°"],"correct":3,"answer":"50°","explanation":"🔑 Góc gấp đôi mỗi nửa: 2 · 25° = <b>50°</b>.<br>✗ 25°: mới là nửa góc, chưa cả góc.<br>✗ 12,5°: chia đôi tiếp, ngược chiều.<br>✗ 155°: 180° − 25°, nhầm kề bù."},{"id":"m3-19","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt hai đường thẳng a và b. Điều kiện nào sau đây đủ để kết luận a ∥ b?","options":["Một cặp góc so le trong bằng nhau","Một cặp góc so le trong bù nhau","Một cặp góc đồng vị bù nhau","Hai góc kề bù bằng nhau"],"correct":0,"answer":"Một cặp góc so le trong bằng nhau","explanation":"🔑 Dấu hiệu: so le trong <b>bằng nhau</b> (hoặc đồng vị bằng nhau) ⇒ a ∥ b.<br>✗ So le trong bù: đó là trong cùng phía.<br>✗ Đồng vị phải bằng nhau, không bù nhau.<br>✗ Kề bù bằng nhau: chỉ cho mỗi góc 90°."},{"id":"m3-20","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt a tại A và cắt b tại B, tạo ra một cặp góc đồng vị bằng nhau. Kết luận nào đúng?","options":["a ⊥ b","a ∥ b","a ⊥ c","a trùng b"],"correct":1,"answer":"a ∥ b","explanation":"🔑 Đồng vị bằng nhau là dấu hiệu ⇒ <b>a ∥ b</b>.<br>✗ a ⊥ b: cần góc giữa a và b bằng 90°.<br>✗ a ⊥ c: đề không cho góc 90° nào.<br>✗ a trùng b: c cắt chúng ở hai điểm A, B."},{"id":"m3-21","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b và đường thẳng c cắt cả hai đường đó. Khi đó các góc so le trong có quan hệ gì?","options":["Bù nhau (tổng bằng 180°)","Có tổng số đo bằng 90°","Bằng nhau","Không có quan hệ gì đặc biệt"],"correct":2,"answer":"Bằng nhau","explanation":"🔑 Nếu một đường thẳng cắt hai đường thẳng song song thì hai góc so le trong <b>bằng nhau</b> (hai góc đồng vị cũng bằng nhau). Ví dụ: một góc so le trong bằng 65° thì góc so le trong kia cũng bằng 65°.<br>✗ Bù nhau (tổng bằng 180°): đó là quan hệ của hai góc trong cùng phía khi a ∥ b, không phải của hai góc so le trong.<br>✗ Có tổng số đo bằng 90°: không có tính chất nào như vậy; hai góc so le trong bằng nhau chứ không cộng thành 90°.<br>✗ Không có quan hệ gì đặc biệt: có quan hệ rất rõ — chúng bằng nhau, đó là tính chất của hai đường thẳng song song."},{"id":"m3-22","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Một góc so le trong bằng 65°. Góc so le trong còn lại của cặp đó bằng bao nhiêu?","options":["115°","25°","130°","65°"],"correct":3,"answer":"65°","explanation":"🔑 a ∥ b ⇒ hai góc so le trong bằng nhau ⇒ góc còn lại cũng bằng <b>65°</b>.<br>✗ 115°: 180° − 65° là quan hệ bù nhau của hai góc trong cùng phía, không phải của hai góc so le trong.<br>✗ 25°: lấy 90° − 65° là vô căn cứ; hai góc so le trong bằng nhau chứ không cộng thành 90°.<br>✗ 130°: nhân đôi 65° là vô căn cứ; không có tính chất nào như vậy."},{"id":"m3-23","ch":3,"topic":"Góc trong cùng phía","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Một góc trong cùng phía bằng 65°. Góc trong cùng phía kia bằng bao nhiêu?","options":["65°","115°","25°","180°"],"correct":1,"answer":"115°","explanation":"🔑 a ∥ b ⇒ hai góc trong cùng phía <b>bù nhau</b> (tổng bằng 180°) ⇒ 180° − 65° = <b>115°</b>.<br>✗ 65°: bằng nhau là quan hệ của cặp góc so le trong hoặc đồng vị, không phải của hai góc trong cùng phía.<br>✗ 25°: lấy 90° − 65° là vô căn cứ; tổng hai góc trong cùng phía là 180°, không phải 90°.<br>✗ 180°: đó là tổng số đo của cả hai góc, không phải số đo của góc còn lại."},{"id":"m3-24","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c, một góc đồng vị bằng 110°. Góc đồng vị tương ứng với nó bằng bao nhiêu?","options":["70°","20°","110°","55°"],"correct":2,"answer":"110°","explanation":"🔑 a ∥ b ⇒ đồng vị bằng nhau ⇒ <b>110°</b>.<br>✗ 70°: 180° − 110°, đó là góc kề bù.<br>✗ 20°: 110° − 90°, phép trừ vô căn cứ.<br>✗ 55°: nửa của 110°, nhầm phân giác."},{"id":"m3-25","ch":3,"topic":"Chiều của mệnh đề","q":"Đường thẳng c cắt hai đường thẳng phân biệt a và b. Khẳng định “Nếu trong các góc tạo thành có một cặp góc so le trong bằng nhau thì a song song với b” được gọi là gì?","options":["Dấu hiệu nhận biết hai đường thẳng song song","Tính chất của hai đường thẳng song song","Tiên đề Euclid về đường thẳng song song","Định nghĩa hai góc kề bù"],"correct":0,"answer":"Dấu hiệu nhận biết hai đường thẳng song song","explanation":"🔑 Đó chính là <b>dấu hiệu nhận biết hai đường thẳng song song</b>: có một cặp góc so le trong bằng nhau (hoặc một cặp góc đồng vị bằng nhau) thì a ∥ b. Ví dụ: hai góc so le trong cùng bằng 60° thì a ∥ b.<br>✗ Tính chất của hai đường thẳng song song: là chiều ngược lại — biết a ∥ b trước, rồi mới suy ra các cặp góc so le trong bằng nhau.<br>✗ Tiên đề Euclid về đường thẳng song song: nói rằng qua một điểm ở ngoài một đường thẳng, chỉ có một đường thẳng song song với đường thẳng đó.<br>✗ Định nghĩa hai góc kề bù: nói về hai góc có một cạnh chung, hai cạnh còn lại là hai tia đối nhau — không liên quan đến song song."},{"id":"m3-26","ch":3,"topic":"Chiều của mệnh đề","q":"Mệnh đề “a ∥ b ⇒ các góc đồng vị bằng nhau” được gọi là gì?","options":["Dấu hiệu nhận biết hai đường thẳng song song","Định nghĩa hai đường thẳng song song","Tính chất của hai đường thẳng song song","Tiên đề Euclid về đường thẳng song song"],"correct":2,"answer":"Tính chất của hai đường thẳng song song","explanation":"🔑 <b>SONG SONG ⇒ GÓC</b> bằng nhau là tính chất.<br>✗ Dấu hiệu: chiều ngược, góc ⇒ a ∥ b.<br>✗ Định nghĩa: hai đường không có điểm chung.<br>✗ Tiên đề Euclid: nói về tính duy nhất."},{"id":"m3-27","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Khẳng định nào sau đây SAI?","options":["Các góc so le trong bằng nhau","Các góc đồng vị bằng nhau","Hai góc trong cùng phía bù nhau","Hai góc trong cùng phía bằng nhau"],"correct":3,"answer":"Hai góc trong cùng phía bằng nhau","explanation":"🔑 Trong cùng phía <b>bù nhau</b> (180°), không bằng nhau ⇒ câu này SAI.<br>✗ So le trong bằng nhau: ĐÚNG.<br>✗ Đồng vị bằng nhau: ĐÚNG.<br>✗ Trong cùng phía bù nhau: ĐÚNG."},{"id":"m3-28","ch":3,"topic":"Góc so le trong","q":"Hai góc so le trong nằm ở vị trí nào so với đường thẳng cắt c?","options":["Cùng một phía của c, ở phần trong giữa a và b","Ở hai phía khác nhau của c, ở phần trong giữa a và b","Cùng một phía của c, ở phần ngoài","Cùng phía của c và ở cùng vị trí so với a, b"],"correct":1,"answer":"Ở hai phía khác nhau của c, ở phần trong giữa a và b","explanation":"🔑 So le trong: phần <b>trong</b>, ở <b>hai phía khác nhau</b> của c.<br>✗ Cùng phía, phần trong: trong cùng phía.<br>✗ Cùng phía, phần ngoài: ngoài cùng phía.<br>✗ Cùng phía, cùng vị trí: đồng vị."},{"id":"m3-29","ch":3,"topic":"Góc đồng vị","q":"Hai góc đồng vị được mô tả như thế nào?","options":["Nằm ở hai phía khác nhau của đường cắt, ở phần trong","Nằm cùng phía của đường cắt và ở cùng vị trí so với hai đường bị cắt","Nằm cùng phía của đường cắt và cả hai đều ở phần trong","Nằm đối đỉnh nhau qua cùng một giao điểm"],"correct":1,"answer":"Nằm cùng phía của đường cắt và ở cùng vị trí so với hai đường bị cắt","explanation":"🔑 Đồng vị: <b>cùng phía</b> c và <b>cùng vị trí</b> so với a, b.<br>✗ Hai phía, phần trong: so le trong.<br>✗ Cùng phía, cả hai trong: trong cùng phía.<br>✗ Đối đỉnh: chung đỉnh, đồng vị thì không."},{"id":"m3-30","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt a và b, tạo ra một cặp góc so le trong lần lượt bằng 70° và 80°. Kết luận nào đúng?","options":["a ∥ b vì hai góc đều là góc nhọn","a ∥ b vì 70° + 80° nhỏ hơn 180°","a không song song với b vì hai góc so le trong không bằng nhau","a ⊥ b"],"correct":2,"answer":"a không song song với b vì hai góc so le trong không bằng nhau","explanation":"🔑 Cần so le trong <b>bằng nhau</b>; 70° ≠ 80° nên a không ∥ b.<br>✗ Cùng là góc nhọn: chưa đủ điều kiện.<br>✗ Tổng nhỏ hơn 180°: không phải dấu hiệu.<br>✗ a ⊥ b: đề không cho góc 90° nào."},{"id":"m3-31","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c, một trong các góc tạo thành bằng 90°. Các góc còn lại bằng bao nhiêu?","options":["Tất cả đều bằng 90°","Một nửa số góc bằng 90°, nửa còn lại bằng 45°","Không xác định được","Tất cả đều bằng 180°"],"correct":0,"answer":"Tất cả đều bằng 90°","explanation":"🔑 Đối đỉnh 90°, kề bù 180° − 90° = 90°, đồng vị 90° ⇒ <b>cả 8 góc vuông</b>.<br>✗ 45°: nửa của 90°, không có chia đôi.<br>✗ Không xác định: xác định được hết.<br>✗ 180°: đó là góc bẹt, không phải góc này."},{"id":"m3-32","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Một góc tạo thành bằng 55°, hỏi góc kề bù với nó bằng bao nhiêu?","options":["55°","35°","125°","110°"],"correct":2,"answer":"125°","explanation":"🔑 Kề bù ⇒ 180° − 55° = <b>125°</b>.<br>✗ 55°: đó là góc đối đỉnh hoặc đồng vị.<br>✗ 35°: 90° − 55°, nhầm phụ nhau.<br>✗ 110°: nhân đôi 55°, vô căn cứ."},{"id":"m3-33","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt hai đường thẳng phân biệt a và b, tạo thành một cặp góc đồng vị cùng có số đo 120°. Kết luận nào đúng?","options":["a ∥ b vì có một cặp góc đồng vị bằng nhau","a không song song với b vì 120° + 120° khác 180°","a ⊥ b","Chưa kết luận được, phải đo thêm cặp góc so le trong"],"correct":0,"answer":"a ∥ b vì có một cặp góc đồng vị bằng nhau","explanation":"🔑 Dấu hiệu nhận biết (SGK): nếu đường thẳng c cắt hai đường thẳng phân biệt a, b và trong các góc tạo thành có một cặp góc so le trong bằng nhau <b>hoặc</b> một cặp góc đồng vị bằng nhau thì a và b song song với nhau. Ở đây cặp góc đồng vị cùng bằng 120° ⇒ a ∥ b.<br>✗ a không song song với b vì 120° + 120° khác 180°: dấu hiệu chỉ cần hai góc đồng vị <b>bằng nhau</b>, không xét tổng của chúng.<br>✗ a ⊥ b: đề không cho góc 90° nào.<br>✗ Chưa kết luận được, phải đo thêm cặp góc so le trong: một cặp góc đồng vị bằng nhau đã đủ để kết luận a ∥ b."},{"id":"m3-34","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b, đường thẳng c cắt a tại điểm A. Hỏi c có cắt b hay không?","options":["Không, vì c ∥ b","Có, c chắc chắn cắt b","Chỉ cắt khi c ⊥ a","Không xác định được"],"correct":1,"answer":"Có, c chắc chắn cắt b","explanation":"🔑 Nếu c ∥ b thì qua A có hai đường ∥ b, trái tiên đề ⇒ <b>c cắt b</b>.<br>✗ c ∥ b: không thể, vì c cắt a mà a ∥ b.<br>✗ Cần c ⊥ a: mọi đường cắt a đều cắt b.<br>✗ Không xác định: tiên đề cho ngay."},{"id":"m3-35","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Nếu a ⊥ c và b ⊥ c (a, b phân biệt) thì hai đường thẳng a và b có quan hệ gì?","options":["a ⊥ b","a trùng b","a cắt b tại một điểm","a ∥ b"],"correct":3,"answer":"a ∥ b","explanation":"🔑 Cùng ⊥ một đường thứ ba ⇒ <b>a ∥ b</b>.<br>✗ a ⊥ b: lỗi kinh điển, phải là ∥.<br>✗ a trùng b: đề nói a, b phân biệt.<br>✗ a cắt b: song song thì không cắt."},{"id":"m3-36","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ∥ b và c ⊥ a. Kết luận nào sau đây đúng?","options":["c ⊥ b","c ∥ b","c ∥ a","c cắt b tạo thành góc 45°"],"correct":0,"answer":"c ⊥ b","explanation":"🔑 ⊥ một trong hai đường ∥ thì ⊥ đường kia ⇒ <b>c ⊥ b</b>.<br>✗ c ∥ b: c cắt a mà a ∥ b nên c cắt b.<br>✗ c ∥ a: trái ngay giả thiết c ⊥ a.<br>✗ 45°: góc đó bằng góc c và a, là 90°."},{"id":"m3-37","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Hai đường thẳng phân biệt a và b cùng vuông góc với đường thẳng c. Khẳng định nào sau đây SAI?","options":["a ∥ b","a và b không có điểm chung","Góc giữa a và c bằng 90°","a ⊥ b"],"correct":3,"answer":"a ⊥ b","explanation":"🔑 a ⊥ c, b ⊥ c ⇒ a ∥ b, nên “a ⊥ b” là khẳng định SAI.<br>✗ a ∥ b: ĐÚNG, là kết luận quy tắc.<br>✗ Không có điểm chung: ĐÚNG, vì a ∥ b.<br>✗ Góc a và c bằng 90°: ĐÚNG, là a ⊥ c."},{"id":"m3-38","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho ba đường thẳng phân biệt a, b, c với a ∥ b và b ∥ c. Quan hệ giữa a và c là gì?","options":["a ⊥ c","a cắt c","a ∥ c","Không xác định được"],"correct":2,"answer":"a ∥ c","explanation":"🔑 Song song có bắc cầu: a ∥ b, b ∥ c ⇒ <b>a ∥ c</b>.<br>✗ a ⊥ c: nhầm ký hiệu ∥ thành ⊥.<br>✗ a cắt c: qua giao điểm có hai đường ∥ b.<br>✗ Không xác định: bắc cầu cho ngay."},{"id":"m3-39","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ⊥ c, b ⊥ c và d ⊥ a (các đường thẳng phân biệt). Quan hệ giữa d và b là gì?","options":["d ∥ b","d cắt b tạo thành góc 45°","d trùng b","d ⊥ b"],"correct":3,"answer":"d ⊥ b","explanation":"🔑 a ⊥ c, b ⊥ c ⇒ a ∥ b; lại có d ⊥ a nên <b>d ⊥ b</b>.<br>✗ d ∥ b: d ⊥ a mà a ∥ b nên d cắt b.<br>✗ 45°: góc đó bằng góc d và a, là 90°.<br>✗ d trùng b: hai đường này còn ⊥ nhau."},{"id":"m3-40","ch":3,"topic":"Ký hiệu ∥ và ⊥","q":"Hai ký hiệu “a ∥ b” và “a ⊥ b” lần lượt có nghĩa là gì?","options":["a vuông góc với b; a song song với b","a song song với b; a vuông góc với b","a bằng b; a cắt b","a cắt b; a trùng b"],"correct":1,"answer":"a song song với b; a vuông góc với b","explanation":"🔑 <b>∥</b> đọc là song song, <b>⊥</b> đọc là vuông góc.<br>✗ Đảo hai ký hiệu là lỗi hay gặp.<br>✗ ∥ không có nghĩa bằng nhau (dấu =).<br>✗ ⊥ không phải trùng nhau, mà là 90°."},{"id":"m3-41","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ∥ b. Nếu đường thẳng c cắt a tạo thành góc 90° thì góc giữa c và b bằng bao nhiêu?","options":["45°","180°","Không xác định được","90°"],"correct":3,"answer":"90°","explanation":"🔑 c ⊥ a và a ∥ b ⇒ c ⊥ b, góc đó bằng <b>90°</b>.<br>✗ 45°: nửa của 90°, không có chia đôi.<br>✗ 180°: đó là góc bẹt, không phải góc này.<br>✗ Không xác định: quy tắc ⊥ với ∥ cho ngay."},{"id":"m3-42","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Khẳng định nào sau đây là ĐÚNG?","options":["Hai đường thẳng phân biệt cùng vuông góc với một đường thẳng thứ ba thì song song với nhau","Hai đường thẳng cùng vuông góc với một đường thẳng thứ ba thì vuông góc với nhau","Hai đường thẳng cùng song song với một đường thẳng thứ ba thì vuông góc với nhau","Hai đường thẳng cắt nhau thì song song với nhau"],"correct":0,"answer":"Hai đường thẳng phân biệt cùng vuông góc với một đường thẳng thứ ba thì song song với nhau","explanation":"🔑 <b>a ⊥ c, b ⊥ c ⇒ a ∥ b</b>: cùng ⊥ một đường thì ∥ nhau.<br>✗ Cùng ⊥ thì ⊥ nhau: kết luận phải là ∥.<br>✗ Cùng ∥ thì ⊥ nhau: cũng phải là ∥ nhau.<br>✗ Cắt nhau thì ∥: tự mâu thuẫn."},{"id":"m3-43","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Bạn Nam viết: “a ⊥ c, b ⊥ c ⇒ a ⊥ b”. Bạn Nam sai ở chỗ nào?","options":["Không sai, kết luận của bạn Nam đúng","Sai ở giả thiết: phải viết là a ∥ c","Sai ở kết luận: phải là a ∥ b","Sai ở kết luận: phải là a trùng b"],"correct":2,"answer":"Sai ở kết luận: phải là a ∥ b","explanation":"🔑 Đúng phải là <b>a ⊥ c, b ⊥ c ⇒ a ∥ b</b>: cùng ⊥ thì SONG SONG.<br>✗ Không sai: kết luận a ⊥ b đã sai.<br>✗ Sai giả thiết: a ⊥ c, b ⊥ c vốn đúng.<br>✗ a trùng b: chỉ là trường hợp riêng."},{"id":"m3-44","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ∥ b, b ∥ c và d ⊥ a (các đường thẳng phân biệt). Kết luận nào đúng về d và c?","options":["d ∥ c","Chỉ biết d ⊥ a, không suy ra được gì về d và c","d trùng c","d ⊥ c"],"correct":3,"answer":"d ⊥ c","explanation":"🔑 a ∥ b, b ∥ c ⇒ a ∥ c; lại có d ⊥ a nên <b>d ⊥ c</b>.<br>✗ d ∥ c: d cắt a mà a ∥ c nên d cắt c.<br>✗ Không suy ra được: bắc cầu rồi dùng ⊥.<br>✗ d trùng c: hai đường này còn ⊥ nhau."},{"id":"m3-45","ch":3,"topic":"Tiên đề Euclid","q":"Qua một điểm nằm ngoài một đường thẳng, có bao nhiêu đường thẳng song song với đường thẳng đó?","options":["Đúng một đường thẳng","Hai đường thẳng","Vô số đường thẳng","Không có đường thẳng nào"],"correct":0,"answer":"Đúng một đường thẳng","explanation":"🔑 Tiên đề Euclid: qua điểm ngoài d chỉ có <b>một</b> đường ∥ d.<br>✗ Hai đường: tiên đề nói duy nhất một.<br>✗ Vô số: đó là số đường kẻ qua điểm đó.<br>✗ Không có: chỉ đúng khi M nằm TRÊN d."},{"id":"m3-46","ch":3,"topic":"Tiên đề Euclid","q":"Điểm M nằm ngoài đường thẳng d. Qua M đã kẻ được đường thẳng a với a ∥ d. Nếu kẻ tiếp một đường thẳng b qua M sao cho b ∥ d thì điều gì xảy ra?","options":["b vuông góc với a","b cắt a tại M","b song song với a","b trùng với a"],"correct":3,"answer":"b trùng với a","explanation":"🔑 Qua M chỉ có một đường ∥ d, nên b <b>trùng a</b>.<br>✗ b ⊥ a: cùng ∥ d thì không thể ⊥ nhau.<br>✗ b cắt a tại M: thành hai đường ∥ d.<br>✗ b ∥ a: cùng qua M thì phải trùng nhau."},{"id":"m3-47","ch":3,"topic":"Tiên đề Euclid","q":"Cho điểm A nằm TRÊN đường thẳng d. Qua A kẻ được bao nhiêu đường thẳng song song với d?","options":["Đúng một đường thẳng","Không có đường thẳng nào","Vô số đường thẳng","Hai đường thẳng"],"correct":1,"answer":"Không có đường thẳng nào","explanation":"🔑 Mọi đường qua A đều có điểm chung A với d ⇒ <b>không có</b> đường nào.<br>✗ Một đường: quên điều kiện A ngoài d.<br>✗ Vô số: đó là số đường kẻ qua A.<br>✗ Hai đường: không đúng trường hợp nào."},{"id":"m3-48","ch":3,"topic":"Tiên đề Euclid","q":"Phát biểu nào sau đây chính là tiên đề về đường thẳng song song?","options":["Qua một điểm nằm ngoài một đường thẳng, chỉ có một đường thẳng song song với đường thẳng đó","Qua một điểm nằm ngoài một đường thẳng, có ít nhất hai đường thẳng song song với đường thẳng đó","Qua một điểm bất kỳ luôn có một đường thẳng song song với mọi đường thẳng cho trước","Hai đường thẳng cùng vuông góc với một đường thẳng thứ ba thì song song với nhau"],"correct":0,"answer":"Qua một điểm nằm ngoài một đường thẳng, chỉ có một đường thẳng song song với đường thẳng đó","explanation":"🔑 Tiên đề: qua điểm <b>ngoài</b> đường thẳng có <b>duy nhất một</b> đường ∥.<br>✗ Ít nhất hai: phá vỡ tính duy nhất.<br>✗ Điểm bất kỳ: điểm phải nằm ngoài d.<br>✗ Cùng ⊥ thì ∥: đó là quy tắc khác."},{"id":"m3-49","ch":3,"topic":"Tiên đề Euclid","q":"Cho đường thẳng d và điểm M không thuộc d. Số đường thẳng đi qua M và số đường thẳng đi qua M song song với d lần lượt là bao nhiêu?","options":["Một và một","Vô số và vô số","Vô số và một","Một và vô số"],"correct":2,"answer":"Vô số và một","explanation":"🔑 Qua M kẻ được <b>vô số</b> đường, chỉ <b>một</b> đường ∥ d.<br>✗ Một và một: qua M có vô số đường.<br>✗ Vô số và vô số: mất tính duy nhất.<br>✗ Một và vô số: đảo ngược cả hai vế."},{"id":"m3-50","ch":3,"topic":"Tiên đề Euclid","q":"Từ tiên đề Euclid, có thể suy ra khẳng định nào sau đây?","options":["Qua một điểm nằm ngoài đường thẳng d, kẻ được vô số đường thẳng song song với d","Hai đường thẳng phân biệt cùng đi qua một điểm thì song song với nhau","Mọi đường thẳng đều song song với nhau","Hai đường thẳng phân biệt cùng song song với một đường thẳng thứ ba thì song song với nhau"],"correct":3,"answer":"Hai đường thẳng phân biệt cùng song song với một đường thẳng thứ ba thì song song với nhau","explanation":"🔑 Hai đường cùng ∥ b mà cắt nhau thì trái tiên đề ⇒ <b>a ∥ c</b>.<br>✗ Vô số đường ∥: tiên đề nói chỉ một.<br>✗ Cùng qua một điểm: chúng cắt nhau ở đó.<br>✗ Mọi đường đều ∥: chúng có thể cắt nhau."},{"id":"m4-1","ch":4,"topic":"Tổng ba góc","q":"Tổng ba góc trong một tam giác bằng bao nhiêu?","options":["∠A + ∠B + ∠C = 180°","∠A + ∠B + ∠C = 360°","∠A + ∠B + ∠C = 90°","∠A + ∠B = ∠C"],"correct":0,"answer":"∠A + ∠B + ∠C = 180°","explanation":"🔑 Tổng ba góc tam giác = 180°.<br>✗ 360°: đó là tứ giác.<br>✗ 90°: hai góc nhọn của tam giác vuông.<br>✗ ∠A + ∠B = ∠C: chỉ đúng khi ∠C = 90°."},{"id":"m4-2","ch":4,"topic":"Tổng ba góc","q":"Tam giác ABC có ∠A = 60°, ∠B = 70°. Số đo của ∠C là bao nhiêu?","options":["∠C = 130°","∠C = 50°","∠C = 60°","∠C = 70°"],"correct":1,"answer":"∠C = 50°","explanation":"🔑 ∠C = 180° − (60° + 70°) = 50°.<br>✗ 130°: mới là tổng hai góc đã cho.<br>✗ 60°: đó là ∠A.<br>✗ 70°: đó là ∠B."},{"id":"m4-3","ch":4,"topic":"Tam giác vuông","q":"Tam giác ABC vuông tại A. Hệ thức nào sau đây đúng?","options":["∠B + ∠C = 180°","∠B + ∠C = 45°","∠B + ∠C = 90°","∠B = ∠C = 90°"],"correct":2,"answer":"∠B + ∠C = 90°","explanation":"🔑 ∠A = 90° nên ∠B + ∠C = 180° − 90° = 90°.<br>✗ 180°: đó là tổng cả ba góc.<br>✗ 45°: là mỗi góc khi vuông cân.<br>✗ Hai góc 90° đã đủ 180°, thừa ∠A."},{"id":"m4-4","ch":4,"topic":"Góc ngoài","q":"Góc ngoài tại một đỉnh của tam giác bằng gì?","options":["Bằng góc trong kề với nó","Bằng 180°","Bằng tổng ba góc trong của tam giác","Bằng tổng hai góc trong không kề với nó"],"correct":3,"answer":"Bằng tổng hai góc trong không kề với nó","explanation":"🔑 Góc ngoài = tổng hai góc trong KHÔNG kề với nó.<br>✗ Góc trong kề: kề bù, tổng 180°.<br>✗ 180°: là góc ngoài + góc trong kề.<br>✗ Tổng ba góc trong luôn 180°, quá lớn."},{"id":"m4-5","ch":4,"topic":"Góc ngoài","q":"Tam giác ABC có ∠A = 50°, ∠B = 65°. Số đo góc ngoài tại đỉnh C là bao nhiêu?","options":["65°","115°","130°","50°"],"correct":1,"answer":"115°","explanation":"🔑 Góc ngoài tại C = ∠A + ∠B = 50° + 65° = 115°.<br>✗ 65°: đó là góc trong ∠B.<br>✗ 130°: là 65° × 2, nhân đôi sai.<br>✗ 50°: đó là góc trong ∠A."},{"id":"m4-6","ch":4,"topic":"Góc ngoài","q":"Góc ngoài tại đỉnh A và góc trong ∠A của tam giác ABC có quan hệ gì?","options":["Chúng kề bù, tổng bằng 180°","Chúng luôn bằng nhau","Chúng phụ nhau, tổng bằng 90°","Góc ngoài luôn gấp đôi góc trong ∠A"],"correct":0,"answer":"Chúng kề bù, tổng bằng 180°","explanation":"🔑 Góc ngoài và góc trong ∠A kề bù ⇒ tổng 180°.<br>✗ Luôn bằng nhau: chỉ khi cả hai = 90°.<br>✗ Phụ nhau 90°: đó là hai góc nhọn.<br>✗ Gấp đôi: chỉ khi ∠A = 60°."},{"id":"m4-7","ch":4,"topic":"Tổng ba góc","q":"Một tam giác có thể có nhiều nhất bao nhiêu góc tù (góc lớn hơn 90°)?","options":["Ba góc tù","Hai góc tù","Không có góc tù nào","Một góc tù"],"correct":3,"answer":"Một góc tù","explanation":"🔑 Tổng chỉ có 180° nên nhiều nhất một góc > 90°.<br>✗ Ba góc tù: tổng đã hơn 270°.<br>✗ Hai góc tù: tổng đã hơn 180°.<br>✗ Không có góc tù: tam giác tù có thật."},{"id":"m4-8","ch":4,"topic":"Tam giác vuông","q":"Trong một tam giác vuông, góc nhọn này gấp đôi góc nhọn kia. Góc nhọn nhỏ hơn bằng bao nhiêu độ?","options":["45°","60°","30°","20°"],"correct":2,"answer":"30°","explanation":"🔑 Hai góc nhọn tổng 90°, nên x + 2x = 90° ⇒ x = 30°.<br>✗ 45°: chỉ đúng khi hai góc bằng nhau.<br>✗ 60°: đó là góc nhọn LỚN.<br>✗ 20°: thì 20° + 40° = 60°, chưa đủ."},{"id":"m4-9","ch":4,"topic":"Tam giác vuông","q":"Tam giác MNP vuông tại M có ∠N = 35°. Số đo ∠P là bao nhiêu?","options":["145°","35°","55°","90°"],"correct":2,"answer":"55°","explanation":"🔑 Hai góc nhọn phụ nhau: ∠P = 90° − 35° = 55°.<br>✗ 145°: là 180° − 35°, quên ∠M = 90°.<br>✗ 35°: đó là ∠N.<br>✗ 90°: đó là ∠M, không có hai góc vuông."},{"id":"m4-10","ch":4,"topic":"Tổng ba góc","q":"Bộ ba số đo nào sau đây KHÔNG thể là ba góc của một tam giác?","options":["100°; 50°; 30°","60°; 60°; 60°","90°; 45°; 45°","80°; 60°; 50°"],"correct":3,"answer":"80°; 60°; 50°","explanation":"🔑 Ba góc phải cộng đúng 180°, mà 80° + 60° + 50° = 190°.<br>✗ 100° + 50° + 30° = 180°: hợp lệ.<br>✗ 60° + 60° + 60° = 180°: tam giác đều.<br>✗ 90° + 45° + 45° = 180°: vuông cân."},{"id":"m4-11","ch":4,"topic":"Trường hợp c-c-c","q":"Trường hợp bằng nhau nào của tam giác chỉ cần so sánh ba cạnh, không cần góc nào?","options":["c-c-c (cạnh - cạnh - cạnh)","c-g-c (cạnh - góc - cạnh)","g-c-g (góc - cạnh - góc)","g-g-g (góc - góc - góc)"],"correct":0,"answer":"c-c-c (cạnh - cạnh - cạnh)","explanation":"🔑 c-c-c: ba cạnh bằng ba cạnh là đủ, không cần góc.<br>✗ c-g-c: còn cần góc XEN GIỮA hai cạnh.<br>✗ g-c-g: còn cần hai góc kề cạnh đó.<br>✗ g-g-g: không phải trường hợp bằng nhau."},{"id":"m4-12","ch":4,"topic":"Trường hợp c-g-c","q":"Trong trường hợp bằng nhau c-g-c, góc bằng nhau phải nằm ở vị trí nào?","options":["Góc đối diện với một trong hai cạnh đã cho","Góc xen giữa hai cạnh đã cho","Góc bất kì trong tam giác cũng được","Góc lớn nhất của tam giác"],"correct":1,"answer":"Góc xen giữa hai cạnh đã cho","explanation":"🔑 c-g-c: góc phải XEN GIỮA đúng hai cạnh đã cho.<br>✗ Góc đối diện: <b>c-c-g</b> không tồn tại.<br>✗ Góc bất kì: quá lỏng, phải xen giữa.<br>✗ Góc lớn nhất: to nhỏ không liên quan."},{"id":"m4-13","ch":4,"topic":"Trường hợp g-c-g","q":"Điều kiện về vị trí của cạnh trong trường hợp bằng nhau g-c-g là gì?","options":["Cạnh dài nhất của tam giác","Cạnh đối diện với một trong hai góc đã cho","Cạnh bất kì cũng được","Cạnh kề với cả hai góc đã cho"],"correct":3,"answer":"Cạnh kề với cả hai góc đã cho","explanation":"🔑 g-c-g: cạnh phải KỀ cả hai góc đã cho.<br>✗ Cạnh dài nhất: dài ngắn không liên quan.<br>✗ Cạnh đối diện: <b>g-g-c</b>, chưa học.<br>✗ Cạnh bất kì: phải nằm giữa hai góc."},{"id":"m4-14","ch":4,"topic":"Trường hợp không hợp lệ","q":"Trường hợp nào sau đây KHÔNG phải là trường hợp bằng nhau của hai tam giác?","options":["c-c-c","c-g-c","g-g-g","g-c-g"],"correct":2,"answer":"g-g-g","explanation":"🔑 g-g-g không phải trường hợp bằng nhau: ba góc chỉ cho cùng hình dạng.<br>✗ c-c-c: hợp lệ, ba cạnh bằng ba cạnh.<br>✗ c-g-c: hợp lệ, góc xen giữa hai cạnh.<br>✗ g-c-g: hợp lệ, cạnh kề hai góc."},{"id":"m4-15","ch":4,"topic":"Trường hợp không hợp lệ","q":"△ABC và △MNP có AB = MN, BC = NP và ∠A = ∠M. Có kết luận được hai tam giác bằng nhau không?","options":["Có, theo trường hợp c-g-c","Không, vì ∠A không xen giữa hai cạnh AB và BC","Có, theo trường hợp c-c-c","Có, theo trường hợp g-c-g"],"correct":1,"answer":"Không, vì ∠A không xen giữa hai cạnh AB và BC","explanation":"🔑 Góc xen giữa AB và BC là ∠B, không phải ∠A ⇒ chưa dùng được c-g-c.<br>✗ c-g-c: đây là bẫy <b>c-c-g</b>.<br>✗ c-c-c: cần ba cặp cạnh, mới có hai.<br>✗ g-c-g: cần hai cặp góc, mới có một."},{"id":"m4-16","ch":4,"topic":"Trường hợp c-g-c","q":"△ABC và △DEF có AB = DE, ∠B = ∠E, BC = EF. Hai tam giác bằng nhau theo trường hợp nào?","options":["c-g-c","c-c-c","g-c-g","Chưa đủ dữ kiện để kết luận"],"correct":0,"answer":"c-g-c","explanation":"🔑 ∠B xen giữa AB, BC và ∠E xen giữa DE, EF ⇒ c-g-c.<br>✗ c-c-c: cần ba cặp cạnh, đề cho hai.<br>✗ g-c-g: cần hai cặp góc, đề cho một.<br>✗ Chưa đủ: góc đã cho đúng là xen giữa."},{"id":"m4-17","ch":4,"topic":"Trường hợp g-c-g","q":"△ABC và △MNP có ∠B = ∠N, BC = NP, ∠C = ∠P. Hai tam giác bằng nhau theo trường hợp nào?","options":["g-c-g","c-g-c","c-c-c","g-g-g"],"correct":0,"answer":"g-c-g","explanation":"🔑 BC kề ∠B và ∠C, NP kề ∠N và ∠P ⇒ g-c-g.<br>✗ c-g-c: cần hai cặp cạnh, đề cho một.<br>✗ c-c-c: cần ba cặp cạnh, đề cho một.<br>✗ g-g-g: không phải trường hợp bằng nhau."},{"id":"m4-18","ch":4,"topic":"Trường hợp c-c-c","q":"△ABC và △DEF có AB = DE, AC = DF, BC = EF. Kết luận nào đúng?","options":["Hai tam giác chỉ cùng hình dạng, chưa chắc bằng nhau","Cần thêm một cặp góc bằng nhau mới kết luận được","△ABC = △DEF theo trường hợp c-c-c","△ABC = △DEF theo trường hợp c-g-c"],"correct":2,"answer":"△ABC = △DEF theo trường hợp c-c-c","explanation":"🔑 Ba cặp cạnh tương ứng bằng nhau ⇒ △ABC = △DEF theo c-c-c.<br>✗ Chỉ cùng hình dạng: đó là g-g-g.<br>✗ Cần thêm góc: c-c-c đã đủ rồi.<br>✗ c-g-c: đề không cho góc nào."},{"id":"m4-19","ch":4,"topic":"Tam giác bằng nhau","q":"Nếu △ABC = △MNP thì cặp cạnh nào sau đây bằng nhau?","options":["AB = NP","AC = MP","BC = MN","AB = MP"],"correct":1,"answer":"AC = MP","explanation":"🔑 △ABC = △MNP ⇒ A↔M, B↔N, C↔P, nên AC = MP.<br>✗ AB = NP: AB ứng với MN.<br>✗ BC = MN: BC ứng với NP.<br>✗ AB = MP: ghép sai cặp đỉnh."},{"id":"m4-20","ch":4,"topic":"Tam giác bằng nhau","q":"Biết △ABC = △DEF và ∠A = 55°. Số đo ∠D là bao nhiêu?","options":["125°","35°","Không xác định được","55°"],"correct":3,"answer":"55°","explanation":"🔑 A ứng với D, góc tương ứng bằng nhau ⇒ ∠D = 55°.<br>✗ 125°: là góc bù của 55°.<br>✗ 35°: là góc phụ của 55°.<br>✗ Không xác định được: góc ứng thì bằng."},{"id":"m4-21","ch":4,"topic":"Trường hợp không hợp lệ","q":"Hai tam giác có ba góc bằng nhau từng đôi một thì kết luận nào đúng?","options":["Chúng bằng nhau theo trường hợp g-g-g","Chúng bằng nhau theo trường hợp g-c-g","Chúng bằng nhau vì tam giác nào cũng có tổng ba góc là 180°","Chưa chắc bằng nhau, vì tam giác này có thể lớn hơn tam giác kia"],"correct":3,"answer":"Chưa chắc bằng nhau, vì tam giác này có thể lớn hơn tam giác kia","explanation":"🔑 Ba góc bằng nhau chỉ cho cùng hình dạng, kích thước có thể khác.<br>✗ g-g-g: không phải trường hợp bằng nhau.<br>✗ g-c-g: đề không cho cặp CẠNH nào.<br>✗ Tổng 180°: tam giác nào cũng vậy."},{"id":"m4-22","ch":4,"topic":"Trường hợp c-g-c","q":"Hai đoạn thẳng AB và CD cắt nhau tại O là trung điểm của mỗi đoạn. Vì sao △OAC = △OBD?","options":["Vì có ba cặp cạnh bằng nhau (c-c-c)","Vì OA = OB, OC = OD và ∠AOC = ∠BOD là hai góc đối đỉnh (c-g-c)","Vì có hai cặp góc bằng nhau và một cặp cạnh (g-c-g)","Vì ba góc của hai tam giác bằng nhau (g-g-g)"],"correct":1,"answer":"Vì OA = OB, OC = OD và ∠AOC = ∠BOD là hai góc đối đỉnh (c-g-c)","explanation":"🔑 OA = OB, OC = OD, ∠AOC = ∠BOD đối đỉnh và xen giữa ⇒ c-g-c.<br>✗ c-c-c: chưa có AC = BD.<br>✗ g-c-g: mới có một cặp góc.<br>✗ g-g-g: không phải trường hợp bằng nhau."},{"id":"m4-23","ch":4,"topic":"Trường hợp c-c-c","q":"△ABC có AB = AC và M là trung điểm của BC. Vì sao △ABM = △ACM?","options":["Vì ∠B = ∠C và BM = CM nên dùng c-g-c","Vì ∠BAM = ∠CAM và AM là cạnh chung nên dùng g-c-g","Vì AB = AC, BM = CM và AM là cạnh chung nên dùng c-c-c","Vì ba góc của hai tam giác bằng nhau nên dùng g-g-g"],"correct":2,"answer":"Vì AB = AC, BM = CM và AM là cạnh chung nên dùng c-c-c","explanation":"🔑 AB = AC (đề cho), BM = CM (M là trung điểm của BC), AM là cạnh chung — ba cặp cạnh bằng nhau ⇒ △ABM = △ACM theo c-c-c.<br>✗ c-g-c với ∠B = ∠C: mới nêu một cặp cạnh, và ∠B = ∠C là điều CHƯA được chứng minh — muốn chứng minh nó lại phải dùng chính hai tam giác này.<br>✗ g-c-g với ∠BAM = ∠CAM: ∠BAM = ∠CAM cũng chưa được chứng minh, đó là điều suy ra SAU khi hai tam giác đã bằng nhau.<br>✗ g-g-g: không phải là trường hợp bằng nhau của tam giác."},{"id":"m4-24","ch":4,"topic":"Trường hợp không hợp lệ","q":"Nhận xét sau đúng hay sai: chỉ cần hai cặp cạnh và một cặp góc bằng nhau là suy ra được hai tam giác bằng nhau?","options":["Sai, góc đó phải là góc xen giữa hai cạnh thì mới kết luận được","Đúng, đó chính là trường hợp c-c-g","Đúng, vì đã có đủ ba yếu tố bằng nhau","Sai, phải có đủ ba cặp cạnh bằng nhau mới kết luận được"],"correct":0,"answer":"Sai, góc đó phải là góc xen giữa hai cạnh thì mới kết luận được","explanation":"🔑 Chỉ khi góc XEN GIỮA hai cạnh (c-g-c) mới kết luận được.<br>✗ <b>c-c-g</b>: không có trường hợp này.<br>✗ Đủ ba yếu tố: sai vị trí vẫn vô ích.<br>✗ Ba cặp cạnh: c-g-c, g-c-g cần ít hơn."},{"id":"m4-25","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Hai tam giác vuông bằng nhau theo trường hợp hai cạnh góc vuông khi nào?","options":["Khi hai cạnh huyền của chúng bằng nhau","Khi hai cạnh góc vuông của tam giác này lần lượt bằng hai cạnh góc vuông của tam giác kia","Khi hai góc nhọn của chúng bằng nhau","Khi một cạnh góc vuông và cạnh huyền bằng nhau"],"correct":1,"answer":"Khi hai cạnh góc vuông của tam giác này lần lượt bằng hai cạnh góc vuông của tam giác kia","explanation":"🔑 Hai cạnh góc vuông của tam giác này lần lượt bằng hai cạnh góc vuông của tam giác kia ⇒ hai tam giác vuông bằng nhau — chính là c-g-c với góc vuông xen giữa.<br>✗ Hai cạnh huyền bằng nhau: chưa đủ, cần thêm một cạnh góc vuông hoặc một góc nhọn bằng nhau nữa.<br>✗ Hai góc nhọn bằng nhau: chỉ cho hai tam giác cùng hình dạng, kích thước vẫn có thể khác nhau.<br>✗ Một cạnh góc vuông và cạnh huyền: đó là trường hợp khác (cạnh huyền – cạnh góc vuông), không phải trường hợp hai cạnh góc vuông."},{"id":"m4-26","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Trường hợp bằng nhau cạnh huyền - góc nhọn của hai tam giác vuông được phát biểu thế nào?","options":["Hai cạnh huyền bằng nhau thì hai tam giác vuông bằng nhau","Hai góc nhọn bằng nhau thì hai tam giác vuông bằng nhau","Cạnh huyền bằng nhau và góc vuông bằng nhau thì hai tam giác vuông bằng nhau","Cạnh huyền và một góc nhọn của tam giác vuông này bằng cạnh huyền và một góc nhọn của tam giác vuông kia thì hai tam giác bằng nhau"],"correct":3,"answer":"Cạnh huyền và một góc nhọn của tam giác vuông này bằng cạnh huyền và một góc nhọn của tam giác vuông kia thì hai tam giác bằng nhau","explanation":"🔑 Cạnh huyền - góc nhọn: phải ĐỦ cả cạnh huyền và một góc nhọn.<br>✗ Chỉ cạnh huyền: béo gầy vẫn khác.<br>✗ Chỉ góc nhọn: chỉ cùng hình dạng.<br>✗ Góc vuông bằng nhau: ai cũng có 90°."},{"id":"m4-27","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Hai tam giác vuông có cạnh huyền bằng nhau và một cạnh góc vuông bằng nhau thì sao?","options":["Bằng nhau, theo trường hợp cạnh huyền - cạnh góc vuông","Chưa chắc bằng nhau vì còn thiếu một cạnh góc vuông nữa","Chỉ bằng nhau khi có thêm điều kiện hai góc nhọn bằng nhau","Không bao giờ bằng nhau"],"correct":0,"answer":"Bằng nhau, theo trường hợp cạnh huyền - cạnh góc vuông","explanation":"🔑 Cạnh huyền + một cạnh góc vuông là trường hợp riêng của tam giác vuông.<br>✗ Thiếu cạnh góc vuông: nó tự khắc bằng.<br>✗ Cần thêm góc nhọn: hai yếu tố đã đủ.<br>✗ Không bao giờ bằng: hiểu ngược định lí."},{"id":"m4-28","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Trường hợp cạnh góc vuông - góc nhọn kề của tam giác vuông tương ứng với trường hợp nào của tam giác thường?","options":["c-c-c","c-g-c","g-c-g","g-g-g"],"correct":2,"answer":"g-c-g","explanation":"🔑 Cạnh góc vuông kề cả góc 90° và góc nhọn ⇒ nằm giữa hai góc: g-c-g.<br>✗ c-c-c: chỉ dùng cạnh, đây có góc.<br>✗ c-g-c: cần hai cạnh, đây chỉ một.<br>✗ g-g-g: không phải trường hợp bằng nhau."},{"id":"m4-29","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Chỉ biết hai tam giác vuông có yếu tố nào sau đây thì VẪN CHƯA kết luận được chúng bằng nhau?","options":["Hai cạnh góc vuông bằng nhau","Cạnh huyền và một góc nhọn bằng nhau","Hai góc nhọn bằng nhau","Cạnh huyền và một cạnh góc vuông bằng nhau"],"correct":2,"answer":"Hai góc nhọn bằng nhau","explanation":"🔑 Hai góc nhọn bằng nhau mà không có cạnh nào ⇒ chưa kết luận được.<br>✗ Hai cạnh góc vuông: trường hợp hợp lệ.<br>✗ Huyền + góc nhọn: trường hợp hợp lệ.<br>✗ Huyền + cạnh góc vuông: hợp lệ."},{"id":"m4-30","ch":4,"topic":"Tam giác vuông bằng nhau","q":"△MNP vuông tại M và △XYZ vuông tại X có NP = YZ, ∠N = ∠Y. Hai tam giác bằng nhau theo trường hợp nào?","options":["Cạnh huyền - góc nhọn","Hai cạnh góc vuông","Cạnh huyền - cạnh góc vuông","Chưa đủ dữ kiện để kết luận"],"correct":0,"answer":"Cạnh huyền - góc nhọn","explanation":"🔑 NP, YZ đối diện góc vuông nên là cạnh huyền; thêm ∠N = ∠Y là đủ.<br>✗ Hai cạnh góc vuông: đề không cho.<br>✗ Huyền - cạnh góc vuông: đề cho góc.<br>✗ Chưa đủ: thật ra đã đủ hai yếu tố."},{"id":"m4-31","ch":4,"topic":"Tam giác vuông bằng nhau","q":"△ABC vuông tại A và △MNP vuông tại M có AB = MN, AC = MP. Kết luận nào đúng?","options":["Chưa kết luận được vì chưa biết cạnh huyền","Bằng nhau theo trường hợp cạnh huyền - góc nhọn","Chưa kết luận được vì chưa biết góc nhọn nào","Bằng nhau theo trường hợp hai cạnh góc vuông"],"correct":3,"answer":"Bằng nhau theo trường hợp hai cạnh góc vuông","explanation":"🔑 AB, AC và MN, MP đều là cạnh góc vuông, hai cặp bằng nhau ⇒ đủ.<br>✗ Chưa biết cạnh huyền: nó tự khắc bằng.<br>✗ Huyền - góc nhọn: đề không cho.<br>✗ Cần góc nhọn: góc 90° đã xen giữa."},{"id":"m4-32","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Vì sao trường hợp hai cạnh góc vuông thực chất chỉ là một dạng của c-g-c?","options":["Vì hai cạnh huyền luôn bằng nhau","Vì góc vuông 90° chính là góc xen giữa hai cạnh góc vuông","Vì hai góc nhọn của tam giác vuông luôn bằng 45°","Vì mọi tam giác vuông đều bằng nhau"],"correct":1,"answer":"Vì góc vuông 90° chính là góc xen giữa hai cạnh góc vuông","explanation":"🔑 Hai cạnh góc vuông kẹp góc 90° ⇒ đúng khuôn c-g-c.<br>✗ Cạnh huyền: là kết quả, không phải lí do.<br>✗ Hai góc nhọn 45°: chỉ khi vuông cân.<br>✗ Mọi tam giác vuông bằng nhau: sai hẳn."},{"id":"m4-33","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Tam giác PQR vuông tại P, tam giác HIK vuông tại H, biết PQ = HI và ∠Q = ∠I. Chúng bằng nhau nhờ trường hợp nào?","options":["Cạnh góc vuông - góc nhọn kề","Cạnh huyền - góc nhọn","Hai cạnh góc vuông","Cạnh huyền - cạnh góc vuông"],"correct":0,"answer":"Cạnh góc vuông - góc nhọn kề","explanation":"🔑 PQ là cạnh góc vuông, ∠Q là góc nhọn KỀ nó — đúng trường hợp này.<br>✗ Huyền - góc nhọn: cần QR = IK.<br>✗ Hai cạnh góc vuông: cần hai cặp cạnh.<br>✗ Huyền - cạnh góc vuông: đề không cho."},{"id":"m4-34","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Trong một tam giác vuông, cạnh huyền là cạnh nào?","options":["Cạnh ngắn nhất của tam giác","Cạnh đối diện với góc vuông","Cạnh cùng với một cạnh khác tạo nên góc vuông","Cạnh đối diện với góc nhọn nhỏ nhất"],"correct":1,"answer":"Cạnh đối diện với góc vuông","explanation":"🔑 Theo SGK, trong tam giác MNP vuông tại M thì MN và MP là hai cạnh góc vuông, còn NP là cạnh huyền — tức cạnh huyền là cạnh đối diện với góc vuông.<br>✗ Cạnh ngắn nhất của tam giác: cạnh huyền được gọi tên theo VỊ TRÍ (đối diện góc vuông), sách không định nghĩa nó theo độ dài.<br>✗ Cạnh cùng với một cạnh khác tạo nên góc vuông: đó là hai cạnh góc vuông (như MN, MP trong tam giác MNP vuông tại M), không phải cạnh huyền.<br>✗ Cạnh đối diện với góc nhọn nhỏ nhất: cạnh huyền đối diện với góc VUÔNG, không đối diện với góc nhọn nào."},{"id":"m4-35","ch":4,"topic":"Tam giác cân","q":"△ABC cân tại A (tức AB = AC) thì hai góc nào bằng nhau?","options":["∠A = ∠B","∠A = ∠C","Cả ba góc đều bằng nhau","∠B = ∠C"],"correct":3,"answer":"∠B = ∠C","explanation":"🔑 Cân tại A: AB = AC ⇔ ∠B = ∠C, hai góc ĐÁY bằng nhau.<br>✗ ∠A = ∠B: ∠A là góc ở đỉnh.<br>✗ ∠A = ∠C: cũng khác, trừ khi đều.<br>✗ Cả ba góc: chỉ đúng với tam giác ĐỀU."},{"id":"m4-36","ch":4,"topic":"Tam giác cân","q":"△ABC cân tại A có ∠A = 40°. Số đo mỗi góc ở đáy là bao nhiêu?","options":["40°","50°","70°","140°"],"correct":2,"answer":"70°","explanation":"🔑 Hai góc đáy bằng nhau: ∠B = ∠C = (180° − 40°) : 2 = 70°.<br>✗ 40°: đó là góc ở đỉnh ∠A.<br>✗ 50°: là 90° − 40°, sai công thức.<br>✗ 140°: mới là tổng hai góc đáy."},{"id":"m4-37","ch":4,"topic":"Tam giác cân","q":"△ABC có ∠B = ∠C = 55°. Kết luận nào đúng?","options":["△ABC là tam giác đều","△ABC vuông tại A","△ABC cân tại A","△ABC cân tại B"],"correct":2,"answer":"△ABC cân tại A","explanation":"🔑 ∠B = ∠C ⇔ AB = AC, nên △ABC cân tại A.<br>✗ Đều: cần ba góc 60°, đây là 55°.<br>✗ Vuông tại A: ∠A = 70°, không phải 90°.<br>✗ Cân tại B: cần ∠A = ∠C, đề không cho."},{"id":"m4-38","ch":4,"topic":"Tam giác đều","q":"Mỗi góc của một tam giác đều bằng bao nhiêu độ?","options":["45°","90°","180°","60°"],"correct":3,"answer":"60°","explanation":"🔑 Tam giác đều có ba góc bằng nhau: 180° : 3 = 60°.<br>✗ 45°: là góc của tam giác vuông cân.<br>✗ 90°: không thể có ba góc vuông.<br>✗ 180°: là tổng CẢ BA góc."},{"id":"m4-39","ch":4,"topic":"Tam giác đều","q":"Dấu hiệu nào sau đây KHÔNG đủ để kết luận một tam giác là tam giác đều?","options":["Tam giác có ba cạnh bằng nhau","Tam giác cân có hai góc ở đáy bằng nhau","Tam giác có ba góc bằng nhau","Tam giác cân có một góc bằng 60°"],"correct":1,"answer":"Tam giác cân có hai góc ở đáy bằng nhau","explanation":"🔑 MỌI tam giác cân đều có hai góc đáy bằng nhau — câu này không thêm gì.<br>✗ Ba cạnh bằng nhau: đó là định nghĩa.<br>✗ Ba góc bằng nhau: mỗi góc 60°, là đều.<br>✗ Cân có góc 60°: cả ba góc thành 60°."},{"id":"m4-40","ch":4,"topic":"Tam giác cân","q":"△ABC cân tại A có ∠B = 50°. Số đo ∠A là bao nhiêu?","options":["80°","50°","65°","130°"],"correct":0,"answer":"80°","explanation":"🔑 Cân tại A nên ∠C = ∠B = 50° ⇒ ∠A = 180° − 100° = 80°.<br>✗ 50°: đó là góc đáy ∠B.<br>✗ 65°: công thức khi 50° là góc ĐỈNH.<br>✗ 130°: quên trừ góc đáy thứ hai."},{"id":"m4-41","ch":4,"topic":"Tam giác cân","q":"Trong tam giác cân, cạnh bên và cạnh đáy được hiểu như thế nào?","options":["Hai cạnh đáy là hai cạnh bằng nhau, cạnh bên là cạnh còn lại","Hai cạnh bên là hai cạnh bằng nhau, cạnh đáy là cạnh còn lại","Cạnh đáy luôn là cạnh dài nhất của tam giác","Cạnh đáy luôn là cạnh nằm ngang ở phía dưới"],"correct":1,"answer":"Hai cạnh bên là hai cạnh bằng nhau, cạnh đáy là cạnh còn lại","explanation":"🔑 Tam giác cân có hai CẠNH BÊN bằng nhau; cạnh thứ ba là cạnh đáy.<br>✗ Nói ngược: chỉ có MỘT cạnh đáy.<br>✗ Đáy dài nhất: đáy có thể ngắn hơn.<br>✗ Nằm ngang: chỉ là cách vẽ hình."},{"id":"m4-42","ch":4,"topic":"Tam giác cân","q":"Tam giác vuông cân tại A có hai góc nhọn bằng bao nhiêu?","options":["30° và 60°","60° và 60°","45° và 45°","90° và 90°"],"correct":2,"answer":"45° và 45°","explanation":"🔑 Vuông tại A: ∠B + ∠C = 90°, lại cân nên mỗi góc 45°.<br>✗ 30° và 60°: tổng 90° nhưng không cân.<br>✗ 60° và 60°: tổng 120°, không vuông được.<br>✗ 90° và 90°: đã có ∠A vuông rồi."},{"id":"m4-43","ch":4,"topic":"Tam giác đều","q":"Một tam giác cân có góc ở đỉnh bằng 60° thì đó là tam giác gì?","options":["Tam giác đều","Tam giác vuông cân","Tam giác tù","Tam giác cân nhưng không đều"],"correct":0,"answer":"Tam giác đều","explanation":"🔑 Hai góc đáy = (180° − 60°) : 2 = 60° ⇒ cả ba góc 60°: tam giác đều.<br>✗ Vuông cân: cần 90° và hai góc 45°.<br>✗ Tù: cần một góc > 90°, đây chỉ 60°.<br>✗ Cân không đều: ba góc bằng nhau là đều."},{"id":"m4-44","ch":4,"topic":"Tam giác cân","q":"Trong tam giác ABC, hai điều \"AB = AC\" và \"∠B = ∠C\" liên hệ với nhau như thế nào?","options":["Chỉ đúng một chiều: có AB = AC mới suy ra được ∠B = ∠C","Chỉ đúng một chiều: có ∠B = ∠C mới suy ra được AB = AC","Chỉ đúng khi △ABC là tam giác đều","Đúng cả hai chiều: AB = AC suy ra ∠B = ∠C và ngược lại"],"correct":3,"answer":"Đúng cả hai chiều: AB = AC suy ra ∠B = ∠C và ngược lại","explanation":"🔑 Cả hai chiều đều đúng: tam giác cân (AB = AC) thì hai góc đáy bằng nhau (∠B = ∠C), và ngược lại tam giác có hai góc bằng nhau thì cân tại A (AB = AC).<br>✗ Chỉ chiều AB = AC suy ra ∠B = ∠C: thiếu chiều ngược — hai góc bằng nhau cũng đủ để kết luận tam giác cân.<br>✗ Chỉ chiều ∠B = ∠C suy ra AB = AC: thiếu chiều xuôi — tam giác cân luôn có hai góc đáy bằng nhau.<br>✗ Chỉ khi tam giác đều: mọi tam giác cân đều đúng, ví dụ AB = AC = 5 cm, BC = 3 cm không đều nhưng vẫn có ∠B = ∠C."},{"id":"m4-45","ch":4,"topic":"Đường trung trực","q":"Đường trung trực của đoạn thẳng AB là đường thẳng như thế nào?","options":["Đường thẳng đi qua trung điểm của AB","Đường thẳng vuông góc với AB","Đường thẳng song song với AB và cách đều A, B","Đường thẳng vuông góc với AB tại trung điểm của AB"],"correct":3,"answer":"Đường thẳng vuông góc với AB tại trung điểm của AB","explanation":"🔑 Trung trực cần ĐỦ hai điều: vuông góc với AB và qua trung điểm AB.<br>✗ Chỉ qua trung điểm: thiếu vuông góc.<br>✗ Chỉ vuông góc: thiếu qua trung điểm.<br>✗ Song song: không bao giờ cắt AB."},{"id":"m4-46","ch":4,"topic":"Đường trung trực","q":"Cho d là đường trung trực của đoạn thẳng AB và điểm M thuộc d. Khi đó ta có điều gì?","options":["MA = MB","MA = AB","MB = AB","MA + MB = AB"],"correct":0,"answer":"MA = MB","explanation":"🔑 Tính chất trung trực: M ∈ d ⇔ MA = MB, cách đều hai đầu mút.<br>✗ MA = AB: không phải tính chất chung.<br>✗ MB = AB: cũng không suy ra được.<br>✗ MA + MB = AB: chỉ khi M nằm giữa A, B."},{"id":"m4-47","ch":4,"topic":"Đường trung trực","q":"Điểm M cách đều hai đầu mút của đoạn thẳng AB, tức MA = MB. Kết luận nào đúng?","options":["M là trung điểm của AB","M nằm trên đoạn thẳng AB","M nằm trên đường trung trực của AB","M nằm ngoài đường trung trực của AB"],"correct":2,"answer":"M nằm trên đường trung trực của AB","explanation":"🔑 Chiều ngược của tính chất: MA = MB ⇔ M thuộc trung trực của AB.<br>✗ Trung điểm: chỉ khi M nằm trên AB.<br>✗ Nằm trên AB: M có thể ở rất xa AB.<br>✗ Nằm ngoài d: ngược hẳn tính chất."},{"id":"m4-48","ch":4,"topic":"Đường trung trực","q":"Đoạn thẳng AB dài 8 cm, đường trung trực d của AB cắt AB tại điểm I. Độ dài IA bằng bao nhiêu?","options":["8 cm","4 cm","2 cm","16 cm"],"correct":1,"answer":"4 cm","explanation":"🔑 I là trung điểm nên IA = IB = 8 : 2 = 4 cm.<br>✗ 8 cm: là cả đoạn AB, chưa chia đôi.<br>✗ 2 cm: là chia cho 4, trung điểm chia 2.<br>✗ 16 cm: là 8 × 2, nhân thay vì chia."},{"id":"m4-49","ch":4,"topic":"Đường trung trực","q":"△ABC cân tại A và M là trung điểm của BC. Đường thẳng AM có tính chất gì đối với BC?","options":["AM là đường trung trực của BC","AM song song với BC","AM đi qua trung điểm nhưng không vuông góc với BC","AM là đường trung trực của AB"],"correct":0,"answer":"AM là đường trung trực của BC","explanation":"🔑 A cách đều B, C và M là trung điểm BC ⇒ AM là trung trực BC.<br>✗ Song song: AM cắt BC tại M.<br>✗ Không vuông góc: sai, vì △ABM = △ACM.<br>✗ Trung trực của AB: AM đi qua mút A."},{"id":"m4-50","ch":4,"topic":"Đường trung trực","q":"Phát biểu nào sau đây về đường trung trực d của đoạn thẳng AB là SAI?","options":["Mọi điểm thuộc d đều cách đều A và B","Mọi điểm cách đều A và B đều nằm ngoài d","d vuông góc với AB tại trung điểm của AB","Trung điểm của AB luôn thuộc d"],"correct":1,"answer":"Mọi điểm cách đều A và B đều nằm ngoài d","explanation":"🔑 Điểm cách đều A và B thì NẰM TRÊN d, không nằm ngoài.<br>✗ Thuộc d thì cách đều A, B: đúng.<br>✗ d vuông góc tại trung điểm: định nghĩa.<br>✗ Trung điểm thuộc d: đúng, là giao điểm."},{"id":"m5-1","ch":5,"topic":"Loại dữ liệu","q":"Chiều cao (cm) của các bạn trong lớp 7A là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính (không là số)","Không phải là dữ liệu","Vừa định lượng vừa định tính"],"correct":0,"answer":"Định lượng (là số)","explanation":"🔑 Chiều cao là SỐ đo được (150 cm) → định lượng.<br>✗ Định tính: không phải số, như màu mắt.<br>✗ Đây vẫn là dữ liệu thống kê.<br>✗ Không thể vừa là số vừa không là số."},{"id":"m5-2","ch":5,"topic":"Loại dữ liệu","q":"Màu mắt (đen, nâu, xanh) của các bạn trong tổ 1 là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính (không là số)","Định lượng vì đếm được số bạn mỗi màu","Không phải dữ liệu thống kê"],"correct":1,"answer":"Định tính (không là số)","explanation":"🔑 Màu mắt ghi bằng TỪ (đen, nâu), không phải số → định tính.<br>✗ Định lượng: phải là số đo hoặc số đếm.<br>✗ Đếm số bạn là bước sau, màu không là số.<br>✗ Đây là dữ liệu thống kê, loại định tính."},{"id":"m5-3","ch":5,"topic":"Loại dữ liệu","q":"Số áo đấu của các cầu thủ đội bóng trường (7, 10, 11, …) là loại dữ liệu nào?","options":["Định lượng, vì được viết bằng chữ số","Định lượng, vì có thể cộng chúng lại","Định tính, vì số áo chỉ dùng để phân biệt cầu thủ","Không phải dữ liệu"],"correct":2,"answer":"Định tính, vì số áo chỉ dùng để phân biệt cầu thủ","explanation":"🔑 Số áo chỉ là MÃ phân biệt cầu thủ, cộng vô nghĩa → định tính.<br>✗ Viết bằng chữ số chưa phải định lượng.<br>✗ Cộng 7 + 10 = 17 chẳng cho biết gì.<br>✗ Đây vẫn là dữ liệu ghi chép được."},{"id":"m5-4","ch":5,"topic":"Loại dữ liệu","q":"Điểm kiểm tra môn Toán của 40 bạn học sinh là loại dữ liệu nào?","options":["Định tính không thể sắp thứ tự","Định tính có thể sắp thứ tự","Không phải dữ liệu thống kê","Định lượng (là số)"],"correct":3,"answer":"Định lượng (là số)","explanation":"🔑 Điểm là SỐ (8; 9,5), tính trung bình được → định lượng.<br>✗ Điểm không định tính vì nó là số.<br>✗ “Sắp thứ tự” chỉ dùng cho định tính.<br>✗ Điểm kiểm tra là dữ liệu thống kê."},{"id":"m5-5","ch":5,"topic":"Loại dữ liệu","q":"Môn học yêu thích của mỗi bạn trong lớp (Toán, Ngữ văn, Tiếng Anh, Thể dục) là loại dữ liệu nào?","options":["Định lượng, vì đếm được có bao nhiêu môn","Định tính (không là số)","Định lượng, vì mỗi môn có một mã số riêng","Vừa định lượng vừa định tính"],"correct":1,"answer":"Định tính (không là số)","explanation":"🔑 Tên môn ghi bằng chữ, không phải số → định tính.<br>✗ Số lượng môn là dữ liệu khác, đây là TÊN.<br>✗ Mã số chỉ để phân biệt, vẫn định tính.<br>✗ Một dãy dữ liệu chỉ thuộc một loại."},{"id":"m5-6","ch":5,"topic":"Loại dữ liệu","q":"Nhóm máu (A, B, AB, O) của các bạn trong lớp là loại dữ liệu nào?","options":["Định lượng vì đếm được số bạn mỗi nhóm","Định lượng vì A, B là kí hiệu toán học","Không phải dữ liệu","Định tính (không là số)"],"correct":3,"answer":"Định tính (không là số)","explanation":"🔑 Nhóm máu ghi bằng chữ A, B, AB, O → định tính.<br>✗ Đếm số bạn không biến nó thành số.<br>✗ A, B chỉ là tên nhóm, không có giá trị số.<br>✗ Nhóm máu là dữ liệu thống kê thường gặp."},{"id":"m5-7","ch":5,"topic":"Loại dữ liệu","q":"Nhiệt độ trung bình (°C) của Hà Nội trong 12 tháng là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính có thể sắp thứ tự","Định tính không thể sắp thứ tự","Không phải dữ liệu thống kê"],"correct":0,"answer":"Định lượng (là số)","explanation":"🔑 Nhiệt độ đo bằng số (17 °C; 28,5 °C) → định lượng.<br>✗ “Sắp thứ tự” chỉ chia nhỏ định tính.<br>✗ Nhiệt độ là số đo nên không định tính.<br>✗ Đây là dữ liệu khí tượng thống kê."},{"id":"m5-8","ch":5,"topic":"Loại dữ liệu","q":"Số học sinh của một trường trong các năm 2020, 2021, 2022, 2023 là loại dữ liệu nào?","options":["Định tính, vì năm học không phải là số đo","Định tính có thể sắp thứ tự","Định lượng (là số)","Không phải dữ liệu"],"correct":2,"answer":"Định lượng (là số)","explanation":"🔑 Số học sinh ĐẾM ĐƯỢC (800; 850) → định lượng.<br>✗ Ta quan tâm SỐ HỌC SINH, năm chỉ là mốc.<br>✗ “Sắp thứ tự” dành cho định tính.<br>✗ Đây là dữ liệu trường thống kê mỗi năm."},{"id":"m5-9","ch":5,"topic":"Loại dữ liệu","q":"Mã lớp ghi trên sổ đầu bài là 71, 72, 73, 74 (ứng với 7A, 7B, 7C, 7D). Đây là loại dữ liệu nào?","options":["Định lượng, vì viết bằng chữ số","Định lượng, vì so sánh lớn bé được","Định tính, vì mã lớp chỉ thay cho tên lớp","Không phải dữ liệu"],"correct":2,"answer":"Định tính, vì mã lớp chỉ thay cho tên lớp","explanation":"🔑 Mã lớp là tên lớp viết bằng số, không đo đếm gì → định tính.<br>✗ Viết bằng chữ số chưa phải định lượng.<br>✗ Lớp 74 “lớn hơn” lớp 71 là vô nghĩa.<br>✗ Đây vẫn là dữ liệu ghi trong sổ."},{"id":"m5-10","ch":5,"topic":"Loại dữ liệu","q":"Cân nặng (kg) của các bạn tổ 2 khi khám sức khỏe đầu năm là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính (không là số)","Định tính có thể sắp thứ tự","Không xếp được vào loại nào"],"correct":0,"answer":"Định lượng (là số)","explanation":"🔑 Cân nặng là số đo (36 kg; 41,5 kg) → định lượng.<br>✗ Định tính không phải số, như tên, màu.<br>✗ “Sắp thứ tự” chỉ dùng cho định tính.<br>✗ Dữ liệu nào cũng thuộc một trong hai loại."},{"id":"m5-11","ch":5,"topic":"Loại dữ liệu","q":"Tên các bạn tổ trưởng của bốn tổ trong lớp là loại dữ liệu nào?","options":["Định lượng vì có 4 bạn tổ trưởng","Định lượng vì mỗi bạn có một số thứ tự trong sổ","Không phải dữ liệu","Định tính (không là số)"],"correct":3,"answer":"Định tính (không là số)","explanation":"🔑 Tên người ghi bằng chữ, không phải số → định tính.<br>✗ “Có 4 bạn” là dữ liệu khác: số lượng.<br>✗ Số thứ tự chỉ để phân biệt, vẫn định tính.<br>✗ Danh sách tên là dữ liệu hợp lệ."},{"id":"m5-12","ch":5,"topic":"Loại dữ liệu","q":"Xếp loại học lực (Tốt, Khá, Đạt, Chưa đạt) của học sinh lớp 7B là loại dữ liệu nào?","options":["Định lượng, vì tương ứng với điểm số","Định tính (không là số)","Không phải dữ liệu thống kê","Định lượng, vì so sánh hơn kém được"],"correct":1,"answer":"Định tính (không là số)","explanation":"🔑 Xếp loại ghi bằng chữ (Tốt, Khá) → định tính, dù sắp thứ tự được.<br>✗ Điểm số là dữ liệu khác, đây là nhãn chữ.<br>✗ Trường thống kê xếp loại mỗi cuối kì.<br>✗ Hơn kém được nhưng “Tốt” vẫn là chữ."},{"id":"m5-13","ch":5,"topic":"Loại dữ liệu","q":"Số điện thoại của phụ huynh ghi trong sổ liên lạc là loại dữ liệu nào?","options":["Định lượng, vì gồm toàn chữ số","Định lượng, vì tính trung bình được","Không phải dữ liệu","Định tính, vì số điện thoại chỉ để liên lạc, không đo đếm gì"],"correct":3,"answer":"Định tính, vì số điện thoại chỉ để liên lạc, không đo đếm gì","explanation":"🔑 Số điện thoại là kí hiệu để liên lạc, cộng vô nghĩa → định tính.<br>✗ Có chữ số nhưng không đo đếm gì.<br>✗ Trung bình các số điện thoại vô nghĩa.<br>✗ Đây vẫn là dữ liệu ghi trong hồ sơ."},{"id":"m5-14","ch":5,"topic":"Loại dữ liệu","q":"Số anh chị em ruột của mỗi bạn trong lớp (0; 1; 2; 3) là loại dữ liệu nào?","options":["Định tính, vì chỉ có vài giá trị","Định tính có thể sắp thứ tự","Định lượng (là số)","Không phải dữ liệu"],"correct":2,"answer":"Định lượng (là số)","explanation":"🔑 Đây là số ĐẾM thật, cộng và tính trung bình được → định lượng.<br>✗ Ít giá trị không làm nó thành định tính.<br>✗ “Sắp thứ tự” chỉ dùng cho định tính.<br>✗ Đây là dữ liệu khảo sát thường gặp."},{"id":"m5-15","ch":5,"topic":"Loại dữ liệu","q":"Dữ liệu ĐỊNH LƯỢNG là dữ liệu như thế nào?","options":["Là dữ liệu được ghi bằng chữ","Là dữ liệu ở dạng SỐ (số liệu)","Là dữ liệu sắp thứ tự được","Là dữ liệu vẽ được biểu đồ"],"correct":1,"answer":"Là dữ liệu ở dạng SỐ (số liệu)","explanation":"🔑 Dữ liệu ĐỊNH LƯỢNG là dữ liệu ở dạng SỐ, còn gọi là số liệu.<br>✗ Ghi bằng chữ chính là định tính.<br>✗ Sắp thứ tự được là cách chia định tính.<br>✗ Loại nào cũng vẽ được biểu đồ."},{"id":"m5-16","ch":5,"topic":"Loại dữ liệu","q":"Trong bốn dữ liệu sau, dữ liệu nào là ĐỊNH TÍNH: chiều cao, cân nặng, màu áo đồng phục, điểm Toán?","options":["Màu áo đồng phục","Chiều cao","Cân nặng","Điểm Toán"],"correct":0,"answer":"Màu áo đồng phục","explanation":"🔑 Màu áo ghi bằng chữ (trắng, xanh) → định tính; ba cái kia là số.<br>✗ Chiều cao đo bằng cm nên là định lượng.<br>✗ Cân nặng đo bằng kg nên là định lượng.<br>✗ Điểm Toán là số 0 đến 10 → định lượng."},{"id":"m5-17","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Xếp loại học lực Giỏi, Khá, Trung bình, Yếu thuộc nhóm dữ liệu định tính nào?","options":["Không thể sắp thứ tự","Có thể sắp thứ tự","Vừa sắp thứ tự được vừa không","Không thuộc nhóm nào vì ghi bằng chữ"],"correct":1,"answer":"Có thể sắp thứ tự","explanation":"🔑 Giỏi hơn Khá, Khá hơn Trung bình → định tính CÓ THỂ sắp thứ tự.<br>✗ Nhóm không sắp được: như màu mắt.<br>✗ Chỉ thuộc một trong hai nhóm.<br>✗ Ghi bằng chữ vẫn chia được hai nhóm."},{"id":"m5-18","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Màu mắt của học sinh (đen, nâu, xanh) thuộc nhóm dữ liệu định tính nào?","options":["Có thể sắp thứ tự vì xếp được theo bảng chữ cái","Có thể sắp thứ tự vì các màu đậm nhạt khác nhau","Không thể sắp thứ tự","Không phải dữ liệu định tính"],"correct":2,"answer":"Không thể sắp thứ tự","explanation":"🔑 Các màu mắt NGANG HÀNG, không màu nào hơn → không sắp thứ tự được.<br>✗ Bảng chữ cái chỉ để dễ tra, không hơn kém.<br>✗ Đậm nhạt không phải tiêu chí phân loại.<br>✗ Màu mắt ghi bằng chữ nên là định tính."},{"id":"m5-19","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Nhóm máu A, B, AB, O thuộc nhóm dữ liệu định tính nào?","options":["Không thể sắp thứ tự","Có thể sắp thứ tự vì A đứng trước B","Có thể sắp thứ tự vì nhóm O hiếm nhất","Là dữ liệu định lượng"],"correct":0,"answer":"Không thể sắp thứ tự","explanation":"🔑 Bốn nhóm máu ngang hàng, không nhóm nào hơn → không sắp thứ tự được.<br>✗ A trước B chỉ là thói quen viết.<br>✗ Độ hiếm là chuyện khác, không tạo thứ tự.<br>✗ Ghi bằng kí hiệu chữ nên là định tính."},{"id":"m5-20","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Mức độ hài lòng với bữa ăn bán trú: Rất hài lòng, Hài lòng, Bình thường, Không hài lòng. Đây là dữ liệu gì?","options":["Định lượng vì có đúng 4 mức","Định tính không thể sắp thứ tự","Định lượng vì chấm điểm được","Định tính có thể sắp thứ tự"],"correct":3,"answer":"Định tính có thể sắp thứ tự","explanation":"🔑 Bốn mức giảm dần từ Rất hài lòng đến Không hài lòng → sắp thứ tự được.<br>✗ “4 mức” là số lựa chọn, trả lời vẫn là chữ.<br>✗ Chúng có thứ tự rõ nên sắp được.<br>✗ Tự gán điểm 1–4 là mã ta đặt, gốc là chữ."},{"id":"m5-21","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Môn thể thao yêu thích (bóng đá, cầu lông, bơi, cờ vua) thuộc nhóm nào?","options":["Định tính có thể sắp thứ tự","Định lượng","Định tính không thể sắp thứ tự","Không phải dữ liệu"],"correct":2,"answer":"Định tính không thể sắp thứ tự","explanation":"🔑 Bốn môn là nhãn ngang hàng, không môn nào trên → không sắp thứ tự được.<br>✗ Sắp thứ tự cần hơn kém như Giỏi – Khá.<br>✗ Tên môn là chữ nên không định lượng.<br>✗ Đây là dữ liệu khảo sát sở thích."},{"id":"m5-22","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Cỡ áo đồng phục S, M, L, XL thuộc nhóm dữ liệu định tính nào?","options":["Không thể sắp thứ tự","Có thể sắp thứ tự","Là dữ liệu định lượng vì đo bằng xăng-ti-mét","Không phải dữ liệu"],"correct":1,"answer":"Có thể sắp thứ tự","explanation":"🔑 S nhỏ hơn M, M nhỏ hơn L, tăng dần → sắp thứ tự được.<br>✗ Chúng hơn kém rõ nên sắp được.<br>✗ Số đo bằng cm là dữ liệu khác, đây là chữ.<br>✗ Cỡ áo là dữ liệu trường thu thập để may."},{"id":"m5-23","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Quê quán của các bạn trong lớp (Hà Nội, Nam Định, Nghệ An, …) thuộc nhóm nào?","options":["Định lượng","Định tính có thể sắp thứ tự theo dân số","Định tính có thể sắp thứ tự theo bảng chữ cái","Định tính không thể sắp thứ tự"],"correct":3,"answer":"Định tính không thể sắp thứ tự","explanation":"🔑 Tên tỉnh là nhãn ngang hàng, không tỉnh nào hơn → không sắp thứ tự được.<br>✗ Tên tỉnh là chữ nên không định lượng.<br>✗ Dân số là dữ liệu khác, không tạo thứ tự.<br>✗ Bảng chữ cái chỉ để dễ tra, không hơn kém."},{"id":"m5-24","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Loại huy chương đạt được trong Hội khỏe Phù Đổng: Vàng, Bạc, Đồng. Đây là dữ liệu gì?","options":["Định tính có thể sắp thứ tự","Định tính không thể sắp thứ tự","Định lượng vì đếm được số huy chương","Không phải dữ liệu"],"correct":0,"answer":"Định tính có thể sắp thứ tự","explanation":"🔑 Vàng cao hơn Bạc, Bạc cao hơn Đồng → định tính sắp thứ tự được.<br>✗ Ba loại có thứ hạng rõ nên sắp được.<br>✗ Số huy chương là dữ liệu khác, đây là LOẠI.<br>✗ Trường thống kê dữ liệu này sau hội thi."},{"id":"m5-25","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Dữ liệu không phải là số (định tính) được chia thành mấy loại, là những loại nào?","options":["Hai loại: có thể sắp thứ tự và không thể sắp thứ tự","Hai loại: định lượng và định tính","Ba loại: chữ, số và kí hiệu","Không chia được thành loại nào"],"correct":0,"answer":"Hai loại: có thể sắp thứ tự và không thể sắp thứ tự","explanation":"🔑 Định tính chia hai loại: CÓ THỂ sắp thứ tự và KHÔNG THỂ sắp thứ tự.<br>✗ Định lượng – định tính là chia chung.<br>✗ Không có cách chia chữ – số – kí hiệu.<br>✗ Định tính luôn thuộc một trong hai loại."},{"id":"m5-26","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Dữ liệu nào sau đây CÓ THỂ sắp thứ tự: nhóm máu; màu tóc; tên món ăn yêu thích; mức độ chăm đọc sách (Hằng ngày – Hằng tuần – Hiếm khi – Không bao giờ)?","options":["Nhóm máu","Màu tóc","Tên món ăn yêu thích","Mức độ chăm đọc sách"],"correct":3,"answer":"Mức độ chăm đọc sách","explanation":"🔑 Hằng ngày nhiều hơn Hằng tuần, giảm dần → sắp thứ tự được.<br>✗ Bốn nhóm máu ngang hàng, không thứ hạng.<br>✗ Các màu tóc chỉ khác, không hơn kém.<br>✗ Tên món ăn là nhãn ngang hàng."},{"id":"m5-27","ch":5,"topic":"Chọn biểu đồ","q":"Muốn biểu diễn TỈ LỆ PHẦN TRĂM học sinh lớp 7A thích từng môn học, nên dùng biểu đồ nào?","options":["Biểu đồ đoạn thẳng","Biểu đồ đoạn thẳng đi lên","Không cần biểu đồ, chỉ cần bảng số liệu","Biểu đồ hình quạt tròn"],"correct":3,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Quạt tròn biểu diễn TỈ LỆ PHẦN TRĂM từng phần so với toàn thể.<br>✗ Đoạn thẳng: dùng cho thay đổi thời gian.<br>✗ Đi lên, đi xuống chỉ hợp dữ liệu thời gian.<br>✗ Đề yêu cầu vẽ biểu đồ cho trực quan."},{"id":"m5-28","ch":5,"topic":"Chọn biểu đồ","q":"Muốn biểu diễn nhiệt độ trung bình của Đà Nẵng trong 12 tháng của năm, nên dùng biểu đồ nào?","options":["Biểu đồ đoạn thẳng","Biểu đồ hình quạt tròn","Biểu đồ hình quạt tròn chia 12 phần bằng nhau","Không biểu diễn được bằng biểu đồ"],"correct":0,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Nhiệt độ thay đổi THEO THỜI GIAN (12 tháng) → biểu đồ đoạn thẳng.<br>✗ Quạt tròn: chỉ cho tỉ lệ phần trăm.<br>✗ Chia 12 tháng thành phần trăm là vô nghĩa.<br>✗ Dữ liệu thời gian vẽ được biểu đồ."},{"id":"m5-29","ch":5,"topic":"Chọn biểu đồ","q":"Số học sinh của trường qua các năm 2019, 2020, 2021, 2022, 2023 nên được biểu diễn bằng biểu đồ nào?","options":["Biểu đồ hình quạt tròn","Biểu đồ đoạn thẳng","Biểu đồ hình quạt tròn chia 5 phần","Không dùng biểu đồ nào cả"],"correct":1,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Dữ liệu gắn với các NĂM, muốn thấy thay đổi → biểu đồ đoạn thẳng.<br>✗ Quạt tròn: so tỉ lệ trong một tổng thể.<br>✗ Các năm không phải phần của tổng 100%.<br>✗ Biểu đồ cho thấy ngay xu hướng tăng giảm."},{"id":"m5-30","ch":5,"topic":"Chọn biểu đồ","q":"Rác thải của trường gồm: rác hữu cơ 50%, giấy 30%, nhựa 20%. Nên dùng biểu đồ nào để biểu diễn?","options":["Biểu đồ đoạn thẳng","Biểu đồ đoạn thẳng gồm 3 điểm","Biểu đồ hình quạt tròn","Không loại biểu đồ nào phù hợp"],"correct":2,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Các phần cộng lại đúng 100% (50% + 30% + 20%) → quạt tròn.<br>✗ Đoạn thẳng: dùng cho dữ liệu thời gian.<br>✗ Ba loại rác không phải ba mốc thời gian.<br>✗ Đây đúng là ca điển hình của quạt tròn."},{"id":"m5-31","ch":5,"topic":"Chọn biểu đồ","q":"Biểu đồ hình quạt tròn dùng để biểu diễn điều gì?","options":["Tỉ lệ phần trăm của từng thành phần so với toàn thể","Sự thay đổi của một đại lượng theo thời gian","Số lớn nhất trong dãy số liệu","Thứ tự xuất hiện của các dữ liệu"],"correct":0,"answer":"Tỉ lệ phần trăm của từng thành phần so với toàn thể","explanation":"🔑 Quạt tròn biểu diễn TỈ LỆ PHẦN TRĂM từng phần, tổng luôn 100%.<br>✗ Thay đổi theo thời gian: đoạn thẳng.<br>✗ Tìm số lớn nhất chỉ là việc đọc dữ liệu.<br>✗ Quạt tròn không cho thấy thứ tự xuất hiện."},{"id":"m5-32","ch":5,"topic":"Chọn biểu đồ","q":"Biểu đồ đoạn thẳng dùng để biểu diễn điều gì?","options":["Tỉ lệ phần trăm các phần của một tổng thể","Số lượng học sinh thuộc mỗi nhóm máu","Sự thay đổi của một đại lượng theo thời gian","Loại của dữ liệu là định tính hay định lượng"],"correct":2,"answer":"Sự thay đổi của một đại lượng theo thời gian","explanation":"🔑 Biểu đồ đoạn thẳng cho thấy SỰ THAY ĐỔI theo THỜI GIAN.<br>✗ Tỉ lệ phần trăm: việc của quạt tròn.<br>✗ Nhóm máu không phải mốc thời gian.<br>✗ Biểu đồ không dùng để phân loại dữ liệu."},{"id":"m5-33","ch":5,"topic":"Chọn biểu đồ","q":"Bạn Mai ghi lại cân nặng của mình vào ngày đầu mỗi tháng trong suốt một năm. Nên vẽ biểu đồ nào?","options":["Biểu đồ quạt tròn với 12 phần","Biểu đồ quạt tròn chia theo phần trăm cân nặng","Không cần biểu đồ vì chỉ theo dõi một người","Biểu đồ đoạn thẳng"],"correct":3,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Cân nặng thay đổi qua các tháng → dùng biểu đồ đoạn thẳng.<br>✗ 12 lần cân không phải 12 phần của tổng.<br>✗ Chia phần trăm cân nặng là vô nghĩa.<br>✗ Một bạn vẫn cần biểu đồ để thấy tăng giảm."},{"id":"m5-34","ch":5,"topic":"Chọn biểu đồ","q":"Khảo sát 200 học sinh về phương tiện đi học và muốn thấy mỗi phương tiện chiếm bao nhiêu phần trăm. Nên dùng biểu đồ nào?","options":["Biểu đồ đoạn thẳng","Biểu đồ hình quạt tròn","Biểu đồ đoạn thẳng vẽ theo từng lớp","Không dùng biểu đồ vì dữ liệu là định tính"],"correct":1,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Cần PHẦN TRĂM từng phương tiện trong 200 học sinh → quạt tròn.<br>✗ Đoạn thẳng: chỉ hợp dữ liệu thời gian.<br>✗ Các lớp không phải mốc thời gian.<br>✗ Định tính vẫn vẽ được sau khi đếm."},{"id":"m5-35","ch":5,"topic":"Chọn biểu đồ","q":"Bạn Nam vẽ biểu đồ hình quạt tròn để biểu diễn nhiệt độ trung bình 12 tháng ở Huế. Nhận xét nào đúng?","options":["Nam làm đúng vì đã có đủ 12 số liệu","Nam làm sai vì quạt tròn chỉ dùng cho tỉ lệ phần trăm của một tổng thể","Nam làm đúng vì hình tròn đẹp và dễ nhìn","Nam làm sai vì biểu đồ quạt tròn nhiều nhất chỉ vẽ được 4 phần"],"correct":1,"answer":"Nam làm sai vì quạt tròn chỉ dùng cho tỉ lệ phần trăm của một tổng thể","explanation":"🔑 Nhiệt độ 12 tháng thay đổi theo thời gian → phải dùng đoạn thẳng.<br>✗ Đủ số liệu vẫn phải chọn đúng biểu đồ.<br>✗ Đẹp, dễ nhìn không phải căn cứ chọn.<br>✗ Quạt tròn không giới hạn 4 phần."},{"id":"m5-36","ch":5,"topic":"Chọn biểu đồ","q":"Bạn Lan dùng biểu đồ đoạn thẳng để biểu diễn tỉ lệ các loại sách trong thư viện (Truyện 45%, Khoa học 35%, Từ điển 20%). Nhận xét nào đúng?","options":["Lan làm đúng vì đã có đủ ba số liệu","Lan làm đúng vì tổng ba tỉ lệ bằng 100%","Lan làm sai vì tổng ba tỉ lệ chưa bằng 100%","Lan làm sai vì đây là tỉ lệ các phần của một tổng thể, phải dùng biểu đồ quạt tròn"],"correct":3,"answer":"Lan làm sai vì đây là tỉ lệ các phần của một tổng thể, phải dùng biểu đồ quạt tròn","explanation":"🔑 Ba loại sách là ba phần của một tổng, không theo thời gian → quạt tròn.<br>✗ Đủ số liệu không có nghĩa chọn đúng.<br>✗ Tổng đúng 100% nhưng vẫn sai loại.<br>✗ 45% + 35% + 20% = 100% nên không thiếu."},{"id":"m5-37","ch":5,"topic":"Chọn biểu đồ","q":"Số lượt khách đến tham quan bảo tàng trong các tháng 1, 2, 3, 4, 5 nên biểu diễn bằng biểu đồ nào?","options":["Biểu đồ quạt tròn vì có 5 phần","Biểu đồ quạt tròn để biết tháng nào đông nhất","Biểu đồ đoạn thẳng","Không biểu diễn được vì số lượt khách quá lớn"],"correct":2,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Dữ liệu theo các THÁNG liên tiếp, muốn thấy tăng giảm → đoạn thẳng.<br>✗ Năm tháng không phải năm phần của tổng.<br>✗ Theo thời gian thì đoạn thẳng rõ hơn.<br>✗ Số lớn vẫn vẽ được nếu chọn đơn vị trục."},{"id":"m5-38","ch":5,"topic":"Chọn biểu đồ","q":"Ở lớp 7C, nhóm máu O chiếm 40%, nhóm A 30%, nhóm B 20%, nhóm AB 10%. Loại biểu đồ nào phù hợp nhất?","options":["Biểu đồ hình quạt tròn","Biểu đồ đoạn thẳng nối bốn nhóm máu","Biểu đồ đoạn thẳng theo thời gian","Cả hai loại biểu đồ đều không phù hợp"],"correct":0,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Bốn nhóm máu là bốn phần của cả lớp, đã có % → quạt tròn.<br>✗ Nối bốn nhóm máu bằng đoạn thẳng: vô nghĩa.<br>✗ Bài này không có mốc thời gian nào.<br>✗ Quạt tròn hoàn toàn phù hợp ở đây."},{"id":"m5-39","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Biểu đồ quạt tròn về môn học yêu thích của lớp 7A cho biết: Toán 40%, Ngữ văn 25%, Tiếng Anh 20%, phần còn lại là Thể dục. Thể dục chiếm bao nhiêu phần trăm?","options":["10%","15%","20%","85%"],"correct":1,"answer":"15%","explanation":"🔑 Tổng luôn 100% → Thể dục = 100% − (40% + 25% + 20%) = 15%.<br>✗ 10% thì tổng chỉ được 95%, thiếu 5%.<br>✗ 20% thì tổng thành 105%, vượt quá.<br>✗ 85% là tổng ba môn đã cho."},{"id":"m5-40","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Tổng các tỉ lệ phần trăm trong một biểu đồ hình quạt tròn luôn bằng bao nhiêu?","options":["100%","Bằng số phần của biểu đồ","Bằng 360% vì hình tròn có 360°","Tùy từng biểu đồ, không cố định"],"correct":0,"answer":"100%","explanation":"🔑 Các phần hợp lại thành toàn thể nên tổng luôn bằng 100%.<br>✗ Số phần chỉ là số miếng của biểu đồ.<br>✗ Hình tròn 360° nhưng tỉ lệ tính theo 100%.<br>✗ Đây là quy tắc cố định, không đổi."},{"id":"m5-41","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Lớp 7B có 40 học sinh. Biểu đồ quạt tròn cho biết 25% số học sinh đi học bằng xe buýt. Có bao nhiêu bạn đi xe buýt?","options":["4 bạn","25 bạn","10 bạn","15 bạn"],"correct":2,"answer":"10 bạn","explanation":"🔑 Lấy tổng số nhân tỉ lệ: 40 × 25 : 100 = 10 (bạn).<br>✗ 4 bạn là 40 : 10, không phải phần trăm.<br>✗ 25 là phần trăm, không phải số bạn.<br>✗ 15 bạn ứng với 37,5%, không khớp đề."},{"id":"m5-42","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Một biểu đồ quạt tròn ghi ba phần lần lượt là 30%, 40% và 20%. Vì sao biểu đồ này chắc chắn có sai sót?","options":["Vì biểu đồ quạt tròn phải có ít nhất 4 phần","Vì tổng mới được 90%, còn thiếu 10% mới đủ toàn thể","Vì các phần phải có tỉ lệ bằng nhau","Vì biểu đồ không ghi rõ số học sinh"],"correct":1,"answer":"Vì tổng mới được 90%, còn thiếu 10% mới đủ toàn thể","explanation":"🔑 Tổng phải là 100%, mà 30% + 40% + 20% = 90% → thiếu 10%.<br>✗ Quạt tròn có thể chỉ gồm 2 hay 3 phần.<br>✗ Các phần được phép to nhỏ khác nhau.<br>✗ Có thể chỉ ghi phần trăm, không ghi số."},{"id":"m5-43","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Biểu đồ đoạn thẳng về nhiệt độ trung bình (°C) cho biết: tháng 1: 17; tháng 2: 19; tháng 3: 22; tháng 4: 27. Tháng nào có nhiệt độ cao nhất?","options":["Tháng 1","Tháng 2","Tháng 3","Tháng 4"],"correct":3,"answer":"Tháng 4","explanation":"🔑 17 &lt; 19 &lt; 22 &lt; 27, lớn nhất là 27 → tháng 4 cao nhất.<br>✗ Tháng 1 chỉ 17 °C, thấp nhất.<br>✗ Tháng 2 có 19 °C, thấp hơn tháng 3.<br>✗ Tháng 3 có 22 °C, chưa cao nhất."},{"id":"m5-44","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Trên biểu đồ đoạn thẳng, đoạn nối hai điểm liên tiếp đi XUỐNG cho ta biết điều gì?","options":["Đại lượng đó tăng lên","Đại lượng đó không thay đổi","Đại lượng đó giảm đi so với thời điểm trước","Số liệu đã bị ghi sai"],"correct":2,"answer":"Đại lượng đó giảm đi so với thời điểm trước","explanation":"🔑 Đi xuống nghĩa là giá trị sau NHỎ HƠN trước → đại lượng giảm.<br>✗ Đoạn đi lên mới là tăng.<br>✗ Không đổi thì đoạn nằm ngang.<br>✗ Đi xuống là bình thường, không phải lỗi."},{"id":"m5-45","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Số học sinh giỏi của một lớp: năm 2020 là 20; năm 2021 là 25; năm 2022 là 35; năm 2023 là 30. Năm nào số học sinh giỏi GIẢM so với năm liền trước?","options":["Năm 2023","Năm 2021","Năm 2022","Không năm nào giảm"],"correct":0,"answer":"Năm 2023","explanation":"🔑 Năm 2023 có 30 bạn, ít hơn 35 của 2022 → giảm 5 bạn.<br>✗ 2021 có 25, nhiều hơn 20 của 2020: tăng.<br>✗ 2022 có 35, nhiều hơn 25 của 2021: tăng.<br>✗ Có một năm giảm, đó là 2023."},{"id":"m5-46","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Biểu đồ quạt tròn về cách đi học của lớp 7D: xe đạp 45%, đi bộ 30%, xe buýt 15%, bố mẹ đưa 10%. Phần lớn nhất của biểu đồ ứng với cách đi học nào?","options":["Đi bộ","Xe đạp","Xe buýt","Bố mẹ đưa"],"correct":1,"answer":"Xe đạp","explanation":"🔑 Phần lớn nhất ứng với tỉ lệ lớn nhất: 45% là của xe đạp.<br>✗ Đi bộ 30%, chỉ đứng thứ hai.<br>✗ Xe buýt 15%, đứng thứ ba.<br>✗ Bố mẹ đưa 10%, phần nhỏ nhất."},{"id":"m5-47","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Trong một biểu đồ hình quạt tròn, một phần chiếm đúng NỬA hình tròn. Phần đó ứng với bao nhiêu phần trăm?","options":["25%","40%","50%","100%"],"correct":2,"answer":"50%","explanation":"🔑 Cả hình tròn là 100% nên một nửa là 100% : 2 = 50%.<br>✗ 25% ứng với một phần tư hình tròn.<br>✗ 40% nhỏ hơn một nửa.<br>✗ 100% là cả hình tròn, không phải nửa."},{"id":"m5-48","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Biểu đồ đoạn thẳng cho biết số cây trường trồng được: năm 2021 là 120 cây; năm 2022 là 150 cây. Số cây năm 2022 thay đổi thế nào so với năm 2021?","options":["Giảm 30 cây","Tăng 150 cây","Tăng 120 cây","Tăng 30 cây"],"correct":3,"answer":"Tăng 30 cây","explanation":"🔑 Lấy số sau trừ số trước: 150 − 120 = 30 → tăng 30 cây.<br>✗ Đoạn đi lên nên là tăng, không giảm.<br>✗ 150 là số cây 2022, không phải mức tăng.<br>✗ 120 là số cây 2021, không phải mức tăng."},{"id":"m5-49","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Biểu đồ quạt tròn của lớp 7A cho biết 20% học sinh thích môn Tin học nhưng không ghi sĩ số lớp. Từ biểu đồ này ta kết luận được gì?","options":["Có đúng 20 bạn thích môn Tin học","Cứ 100 bạn thì có 20 bạn thích Tin học; muốn biết số bạn cụ thể phải biết sĩ số lớp","Không kết luận được điều gì từ biểu đồ này","Tin học là môn được thích nhất lớp"],"correct":1,"answer":"Cứ 100 bạn thì có 20 bạn thích Tin học; muốn biết số bạn cụ thể phải biết sĩ số lớp","explanation":"🔑 Quạt tròn chỉ cho TỈ LỆ; muốn ra số bạn phải nhân với sĩ số.<br>✗ 20% không phải 20 bạn: lớp 40 thì là 8.<br>✗ Vẫn kết luận được về tỉ lệ.<br>✗ Thích nhất hay không còn phải so môn khác."},{"id":"m5-50","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Số lượt bạn đọc mượn sách ở thư viện: tháng 9: 120; tháng 10: 150; tháng 11: 180; tháng 12: 210. Nhận xét nào đúng về biểu đồ đoạn thẳng của dãy số liệu này?","options":["Đường biểu diễn đi lên đều, số lượt mượn tăng dần qua các tháng","Đường biểu diễn đi xuống, số lượt mượn giảm dần","Đường biểu diễn nằm ngang vì tháng nào cũng có bạn mượn sách","Phải dùng biểu đồ quạt tròn mới thấy được xu hướng"],"correct":0,"answer":"Đường biểu diễn đi lên đều, số lượt mượn tăng dần qua các tháng","explanation":"🔑 120 &lt; 150 &lt; 180 &lt; 210 → đường đi lên đều, mỗi tháng tăng 30.<br>✗ Đi xuống chỉ khi số liệu giảm dần.<br>✗ Nằm ngang chỉ khi các tháng bằng nhau.<br>✗ Quạt tròn không thấy được thay đổi."}];

